export function install() { // page-split: install
	// page-split: install 49
	// The lower pane of the rail: who you are, how Daimond is set up, and what it is
	// costing. Configuring Daimond is not a popup — the forms that ask the user for
	// something (a provider key, a mailbox) open HERE, with the chat still
	// running beside them, so the user can ask Daimond which password a mailbox wants and
	// read the answer while the box asking for one is on screen.
	//
	// It has a status header, which is always on, and a body showing one of
	// three views:
	//
	//   home      what it rests on: the account's own controls
	//   settings  the provider key and credits, reached from home
	//   form      built on demand, and gone again when it is answered
	//
	// A view that is finished with returns to home. Nothing stays on screen
	// after it has done its job — which is what a modal got right and what a
	// panel has to be told.
	//
	// Where there is no rail there is no panel, and no room for a chat beside a
	// form either: a phone, or the band where the rail folds away. There the
	// settings view is MOVED into a modal card and a form falls back to a
	// dialog. One settings form exists in the document; it changes host.
	/* var */ DaimondAdmin = (function () {
		var body, homeView, settingsView, creditsView, releaseView, pushView, formView, modal, slot, closeBtn;
		var limitsView, searchView, foldersView;   // Settings sections reached from a home row
		var adminWrap, titleEl;   // #admin (toggles .admin-open) and the drawer title
		var drawerOpen = false;
		// Which of the two forms is on screen. The panel used to hold one view (Settings, which
		// carried both the model and the credits); it now holds two, each reached from the status
		// row that names it, so the mover has to be told which one it is moving.
		var curView = null;
		var escaper = null;      // the current form's key handler

		/// Is the rail actually on screen? Not "is it open" — the rail folds
		/// itself away below 1280px, and on a phone it is one tab of four.
		function available() {
			var el = document.getElementById('panel-rail');
			return !!el && el.offsetParent !== null;
		}

		/// Every view but home and the form, which each have rules of their own.
		function views() {
			return [settingsView, creditsView, releaseView, pushView, limitsView, searchView, foldersView];
		}
		/// Put every view in `views` away. Version too: it was once the one view nothing
		/// put away, so the drawer re-opened with the release history still hanging below
		/// whatever was asked for next.
		function hideViews() {
			views().forEach(function (v) { if (v) v.style.display = 'none'; });
		}

		/// Put the open view back in the panel, and take the modal down.
		///
		/// Every view the modal can host, not just the two it started with: Version
		/// and a built form can be in there too, and one left behind in the slot is
		/// a view the panel can no longer show. The form goes back FIRST, because
		/// the others are inserted relative to it and `insertBefore` needs it to be
		/// a child of `body` already.
		function toPanel() {
			if (formView && formView.parentNode !== body) body.appendChild(formView);
			views().forEach(function (v) {
				if (v && v.parentNode !== body) body.insertBefore(v, formView);
			});
			modal.style.display = 'none';
			DaimondLayers.done('admin-view');
		}
		/// The head the hosted view wears in the modal: what it is, and a × to close it.
		///
		/// The phone hides the modal's own heading and Close (mobile.css) because the
		/// view inside used to carry a header; the rail split moved that head outside
		/// the slot, leaving an untitled modal with no visible way out. This puts one
		/// back where the phone CSS already styles it.
		var modalHeadEl = null, modalHeadTitle = null;
		/// What the modal head's × does. Closing the drawer is right for a view; for
		/// a FORM it would abandon a promise the caller is still waiting on, so the
		/// form's own cancel is used instead and the answer is delivered.
		var headClose = null;
		function modalHead(title, onClose, key) {
			if (!modalHeadEl) {
				modalHeadEl = document.createElement('div');
				modalHeadEl.className = 'admin-view-head';
				modalHeadTitle = document.createElement('div');
				modalHeadTitle.className = 'admin-title';
				// The drawn cross, at the thumb's floor: `closerFor` is the app's one
				// closer, and `admin-back` rides along as the hook the modal's own
				// rules reach for.
				var x = closerFor(t('admin.settings'), 'admin-back');
				x.addEventListener('click', function () { (headClose || closeAdmin)(); });
				modalHeadEl.appendChild(modalHeadTitle);
				modalHeadEl.appendChild(x);
			}
			headClose = onClose || null;
			if (key) DaimondI18n.bind(modalHeadTitle, '', key);
			else mark(modalHeadTitle, '', title || t('admin.settings'));
			// Always first: the view is appended after it, and a re-open must not
			// leave the head stranded below the view it names.
			if (slot.firstChild !== modalHeadEl) slot.insertBefore(modalHeadEl, slot.firstChild);
		}

		/// Host the open view in the modal card, for a window with no rail in it.
		///
		/// A form brings a head of its own, but `#settings-slot .admin-view-head` is
		/// hidden by the desktop stylesheet, so in the modal the form would be
		/// nameless. The modal's head carries the name instead, with its × pointed
		/// at the form's cancel so backing out still answers the caller.
		function toModal(title, formMode, key) {
			var v = formMode ? formView : (curView || settingsView);
			modalHead(title, formMode ? cancelForm : null, key);
			slot.appendChild(v);
			v.style.display = '';
			var down = modal.style.display === 'none';
			modal.style.display = 'flex';
			// The card is the scroller and the head with the × is its first child. A
			// browser gives a card that was scrolled, closed and shown again its old
			// offset, so a view hosted anew starts at its head, not below the ×.
			if (down) { var card = modal.querySelector('.modal-card'); if (card) card.scrollTop = 0; }
			// What Back does here is what the head's × does: cancel a form, close a view.
			DaimondLayers.open('admin-view', function () { (headClose || closeAdmin)(); });
		}

		/// Back out of the built form the way its own × does, so the promise the
		/// caller is waiting on resolves to "cancelled" rather than never resolving.
		function cancelForm() {
			var back = formView && formView.querySelector('.admin-back');
			if (back) back.click();
			else closeAdmin();
		}
		function endForm() {
			if (escaper) { document.removeEventListener('keydown', escaper, true); escaper = null; }
			formView.innerHTML = '';
			formView.style.display = 'none';
		}

		/// Bring the Admin drawer into view on `title`. In form mode the drawer's
		/// own header is hidden, because the form supplies its own. Opening arms the
		/// click-away close.
		var drawerOpener = null;		// what to give the keyboard back to

		function showDrawer(title, formMode, key) {
			// On a phone the panel's home is the drawer, so the drawer comes first:
			// opened while the drawer was put away, the panel rode the closed drawer
			// off the left edge and under its `visibility: hidden`, and Back with it
			// (FIRE ublk30b, flow backlog of 18 Oct). Opening it here puts the drawer
			// layer under Admin's, which is where Back from Admin lands anyway.
			if (window.DaimondShell && DaimondShell.isPhone && DaimondShell.isPhone()
				&& !document.body.classList.contains('drawer-open')) DaimondShell.openDrawer();
			if (adminWrap) {
				adminWrap.classList.add('admin-open');
				adminWrap.classList.toggle('admin-form-mode', !!formMode);
			}
			// The heading has to carry its key, because it was the one thing on the
			// drawer that stayed in the language it was opened in even after the
			// view below it had been redrawn. An opener knows its key and hands it
			// over; a caller of `form` does not, and its title is traced back from
			// the words instead.
			if (titleEl) {
				if (key) DaimondI18n.bind(titleEl, '', key);
				else mark(titleEl, '', title || t('admin.settings'));
			}
			if (!drawerOpen) {
				drawerOpen = true;
				// Back does what the form's own × does when a form is up, so the caller's promise is answered.
				DaimondLayers.open('admin', function () { if (escaper) cancelForm(); else closeAdmin(); });
				// What had the keyboard when the drawer went up, so its closer can
				// give it back. Only on the way IN: switching from Home to Models is
				// not a new opening, and taking the reading again there would make
				// the drawer's own last-clicked row the thing focus went home to.
				drawerOpener = document.activeElement;
				// Defer, so the very click that opened the drawer does not close it.
				setTimeout(function () {
					if (drawerOpen) document.addEventListener('mousedown', outsideClose, true);
				}, 0);
			}
		}

		/// A click outside #admin dismisses the drawer. The Status rows and the
		/// identity row are INSIDE #admin, so acting on them never trips this.
		///
		/// A dialog is not "outside". Dialogs are appended to `document.body`, so
		/// the drawer counted every click in one as a click away from itself: the
		/// user opened Admin, chose "Change name…", pressed Cancel, and the Admin
		/// drawer they had come from was gone behind it — along with the focus,
		/// since the button that opened the dialog was now inside a hidden view and
		/// could no longer take it back.
		///
		/// Nor is a model list (`.mp-pop`, models.js). It too is drawn on the body, so a
		/// press on a row of the Models panel's drafting pulldown, or the add-provider
		/// form's, shut the drawer under it before the row could be chosen.
		function outsideClose(e) {
			if (!adminWrap || adminWrap.contains(e.target)) return;
			if (e.target && e.target.closest && e.target.closest('.modal, .pair-scrim, .pal-scrim, .mp-pop')) return;
			closeAdmin();
		}

		/// Take the Admin drawer away — "finished". The rail is just the list and
		/// the Status strip again.
		function closeAdmin() {
			endForm();
			toPanel();                       // if it was in the modal, bring it back + drop it
			hideViews();
			if (homeView) homeView.style.display = 'none';
			curView = null;
			if (adminWrap) adminWrap.classList.remove('admin-open', 'admin-form-mode');
			drawerOpen = false;
			DaimondLayers.done('admin');
			document.removeEventListener('mousedown', outsideClose, true);
			// The keyboard goes back to whatever opened the drawer -- the identity
			// row, usually. Left alone it fell to the document body, and the next
			// Tab started again from the top of the app.
			if (drawerOpener && drawerOpener.focus && drawerOpener.getClientRects
				&& drawerOpener.getClientRects().length) {
				try { drawerOpener.focus(); } catch (e) { /* gone with the redraw */ }
			}
			drawerOpener = null;
		}

		/// The resting menu, shown IN the open drawer: the account's controls and
		/// the way to connect a model. Reached by the identity row, or Back.
		function home() {
			homeContent();
			showDrawer(t('admin.settings'), false, 'admin.settings');
		}

		/// Put the home view in order WITHOUT summoning the drawer.
		///
		/// Rendering and opening used to be one call, and unlocking used it to
		/// bring the account's controls up to date -- so every sign-in ended with
		/// the Admin drawer standing open over the app, whether or not the user
		/// had closed it the time before. The drawer is a transient surface, as
		/// its own stylesheet says: summoned, and gone again when finished.
		/// Nothing but a deliberate act of the user's should open it.
		function homeContent() {
			endForm();
			toPanel();
			hideViews();
			curView = null;
			homeView.style.display = '';
			renderHome();
		}
		var closeModal = closeAdmin;

		/// Show the models. `note` is the reason the user was sent here — the message that used to
		/// be the modal's subtitle ("Connect a provider to start this chat").
		function settings(note) {
			endForm();
			homeView.style.display = 'none';
			hideViews();
			curView = settingsView;
			settingsView.style.display = '';
			document.getElementById('byok-note').textContent = note || '';
			if (window.DaimondModels) DaimondModels.render();
			if (available()) { toPanel(); showDrawer(t('drawer.models'), false, 'drawer.models'); }
			else toModal(t('drawer.models'), false, 'drawer.models');
		}

		/// Show what you are running, and what came before it. Reached from the
		/// status row that names the release, in the panel rather than over the
		/// top of the work, like everything else the Admin panel holds.
		function release() {
			endForm();
			homeView.style.display = 'none';
			hideViews();
			curView = releaseView;
			releaseView.style.display = '';
			drawRelease();
			if (available()) { toPanel(); showDrawer(t('rel.whats_new'), false, 'rel.whats_new'); }
			else toModal(t('rel.whats_new'), false, 'rel.whats_new');
		}

		/// Draw the release history into its view. Its own function because the
		/// language can change while it is on screen, and a repaint has to be the
		/// same drawing rather than a second one that drifts from it.
		function drawRelease() {
			if (!window.DaimondRelease) return;
			var relList = document.getElementById('rel-list');
			var drawn = DaimondRelease.render(relList);
			// The build ids in the history are the strings a bug report quotes,
			// so each gets the same button the rest of the app uses. Applied
			// after the render rather than inside it: the rows come from the
			// transparency log, and decorating them here keeps ONE copy helper
			// for the whole app instead of a second one alongside it.
			if (drawn && drawn.then) {
				drawn.then(function () { addBuildCopies(relList); }, function () { /* no log */ });
			} else { addBuildCopies(relList); }
		}

		/// Put a copy button beside every build id in the version history.
		function addBuildCopies(list) {
			if (!list) return;
			var codes = list.querySelectorAll('.rel-build-head code, .rel-meta code');
			for (var i = 0; i < codes.length; i++) {
				var c = codes[i];
				var id = (c.textContent || '').trim();
				if (!id) continue;
				// Named by the id itself: a panel can hold twenty of these, and
				// twenty buttons called "Copy build id" tell a listener nothing
				// about which build each one is.
				c.parentNode.insertBefore(
					idCopyBtn(tOr('copy.what_build_n', 'build {id}', { id: id }), id),
					c.nextSibling);
			}
		}

		/// Show the credits. They used to sit under the model settings, in one form that answered
		/// two unrelated questions; each is now reached from the status row that names it.
		function credits(note) {
			endForm();
			homeView.style.display = 'none';
			hideViews();
			curView = creditsView;
			creditsView.style.display = '';
			drawCredits(note);
			if (available()) { toPanel(); showDrawer(t('drawer.credits'), false, 'drawer.credits'); }
			else toModal(t('drawer.credits'), false, 'drawer.credits');
		}

		/// Draw the credits view. Its own function because a language change has
		/// to produce the same drawing as an open does, not a second one that
		/// drifts from it.
		function drawCredits(note) {
			var n = document.getElementById('credits-note');
			if (n) mark(n, '', note || '');
			renderCredits();
			if (window.DaimondCredits) DaimondCredits.render();
			// Again, AFTER renderCredits -- which blanks this line for an authed account, and
			// so wiped the caller's reason for sending the user here on the way in. Whoever
			// opened Credits said why; the drawer should still be saying it when it arrives.
			if (n && note) mark(n, '', note);
			// The standing instruction to buy more credits belongs with the credits, not in a
			// settings page of its own: the question "what happens when these run out" is asked
			// while looking at how many are left.
			if (window.DaimondAutoReload) DaimondAutoReload.render();
		}

		/// Show the push credential: which host a push reaches, and the box to set it.
		///
		/// Its own view rather than a row in Models for the reason given in
		/// `index.html`: a token that writes to the user's repositories is not the
		/// same kind of secret as a key that buys tokens from a provider.
		function push() {
			endForm();
			homeView.style.display = 'none';
			hideViews();
			if (!pushView) return;
			curView = pushView;
			pushView.style.display = '';
			fillPushSettings();
			if (available()) { toPanel(); showDrawer(t('drawer.push'), false, 'drawer.push'); }
			else toModal(t('drawer.push'), false, 'drawer.push');
		}

		/// Show one of the Settings sections a home row opens -- Limits, Search, Folders --
		/// drawn by `draw`, under the heading `key` names.
		///
		/// Their controls stood in Models until D-20261018-09 U4, thirteen selects of turn
		/// limits, a search engine and two folders in a view named for the models. Only the
		/// controls moved: every one still reads and writes the key it always did.
		function section(view, key, draw) {
			if (!view) return;
			endForm();
			homeView.style.display = 'none';
			hideViews();
			curView = view;
			view.style.display = '';
			draw();
			if (available()) { toPanel(); showDrawer(t(key), false, key); }
			else toModal(t(key), false, key);
		}
		function drawSearch()  { SearchRow.render(); }
		function drawFolders() { TermRootRow.renderGrant(); TermRootRow.render(); }
		function limits()  { section(limitsView,  'drawer.limits',  renderLimitRows); }
		function search()  { section(searchView,  'drawer.search',  drawSearch); }
		function folders() { section(foldersView, 'drawer.folders', drawFolders); }

		/// Redraw home if it is the view standing open, and leave any other alone.
		function refreshHome() {
			var up = drawerOpen || (modal && modal.style.display !== 'none');
			if (!up || !homeView || homeView.style.display === 'none') return;
			try { renderHome(); } catch (e) { console.warn('admin: home would not redraw', e); }
		}

		// ── Following a language change ───────────────────────
		//
		// The drawer is the app's largest translated surface and the one most
		// often standing open, so it was also the one most visibly stuck in the
		// language it was opened in: switching to Japanese with Admin up left the
		// whole drawer in Spanish until it was closed and opened again.
		//
		// Each view says ONCE how to draw itself, beside where it is defined, and
		// `repaint` redraws whichever is up without knowing what they are. A view
		// added later is covered by joining this list rather than by remembering
		// to add a line to a change handler in another part of the file -- which
		// is the shape that let this come back after it was fixed the first time.
		var painters = [];
		function painter(el, draw) { if (el && typeof draw === 'function') painters.push({ el: el, draw: draw }); }

		/// Redraw whatever the drawer is showing, in the language now in force.
		function repaint() {
			painters.forEach(function (p) {
				if (p.el.style.display === 'none' || !p.el.getClientRects().length) return;
				try { p.draw(); } catch (e) { console.warn('admin repaint failed', e); }
			});
		}

		/// The cog: open the Admin drawer on its menu, or close it if it is open.
		function toggleSettings() {
			if (drawerOpen) closeAdmin();
			else home();
		}

		/// Ask the user to fill something in. Resolves the values, or null if
		/// they backed out. The options are a dialog's options, so the fallback
		/// is the dialog itself.
		function form(opts) {
			if (!available()) return dialog(opts);
			var opener = document.activeElement;   // captured before anything moves it
			toPanel();
			showDrawer(opts.title || t('admin.settings'), true);
			return new Promise(function (resolve) {
				homeView.style.display = 'none';
				settingsView.style.display = 'none';
				formView.innerHTML = '';
				formView.style.display = '';

				var head = document.createElement('div');
				head.className = 'admin-view-head';
				var title = document.createElement('div');
				title.className = 'admin-title';
				mark(title, '', opts.title || '');
				// The same drawn cross, at the same thumb's floor, as every other
				// way out in the app. It was a '×' character in a 2x6px box.
				var back = closerFor(opts.title || t('common.cancel'), 'admin-back');
				mark(back, 'title', t('common.cancel'));
				head.appendChild(title);
				head.appendChild(back);
				formView.appendChild(head);

				if (opts.message) {
					var p = document.createElement('p');
					p.className = 'dlg-msg';
					mark(p, '', opts.message);                 // escaped
					formView.appendChild(p);
				}

				var f = buildForm(formView, opts);

				var err = document.createElement('div');
				err.className = 'dlg-err';
				formView.appendChild(err);

				var row = document.createElement('div');
				row.className = 'dlg-actions';
				var cancel = document.createElement('button');
				cancel.type = 'button';
				cancel.className = 'modal-close dlg-cancel';
				mark(cancel, '', opts.cancelLabel || t('common.cancel'));
				var ok = document.createElement('button');
				ok.type = 'button';
				ok.className = 'dlg-ok';
				mark(ok, '', opts.okLabel || t('dlg.ok'));
				row.appendChild(cancel);
				row.appendChild(ok);
				formView.appendChild(row);

				// Whatever opened this form is where the keyboard belongs when the
				// form is finished with. Left alone, focus fell to the document body
				// and the next Tab started again from the top of the app.
				function done(v) {
					closeAdmin();
					if (opener && opener.focus && opener.getClientRects().length) {
						try { opener.focus(); } catch (e) { /* gone with the drawer */ }
					}
					resolve(v);
				}
				async function submit() {
					var vals = f.read();
					var bad = opts.validate ? await opts.validate(vals) : '';
					if (bad) { err.textContent = bad; return; }
					done(vals);
				}
				escaper = function (e) {
					if (!formView.contains(document.activeElement)) return;
					if (e.key === 'Enter') { e.preventDefault(); submit(); }
				};
				document.addEventListener('keydown', escaper, true);
				back.addEventListener('click', function () { done(null); });
				cancel.addEventListener('click', function () { done(null); });
				ok.addEventListener('click', submit);

				if (f.first) { f.first.focus(); f.first.select(); }
			});
		}

		// ── Home ──────────────────────────────────────────────
		// The account's own controls. They used to be a floating menu anchored to
		// the user row; a panel that exists to hold them is a better home than a
		// popup that has to be dismissed.
		/// Redraw the home view, keeping the focus where it was.
		///
		/// A REDRAW MUST NOT TAKE THE FOCUS WITH IT. `renderConsoleLink` calls this
		/// on every answer from the console role probe, and when nothing answers it
		/// retries on a timer at 1.2s, 2.4s and 3.6s -- which is every session with
		/// no gateway. So a redraw lands about half a second AFTER a dialog has
		/// handed the focus back to the button that opened it: the button is
		/// replaced, and the focus falls to `document.body`, so the next Tab starts
		/// at the top of the app.
		///
		/// That is what `verify_focus` was reporting against three dialogs, and the
		/// cause was here rather than in any of them -- the restore worked and was
		/// then undone. Measured with `dev/probe_focusrestore.mjs`: the focus is on
		/// the opener at +50ms and +300ms, and on the body by +900ms.
		///
		/// Controls are matched back by their label, which is what identifies one to
		/// the person using it. An item that has genuinely gone -- the panel now
		/// offers something different -- simply keeps no focus, which is correct: it
		/// is the container that survives, not a promise about its contents.
		function renderHome() {
			var hadFocus = homeView && document.activeElement
				&& homeView.contains(document.activeElement)
				? (document.activeElement.textContent || '').trim() : '';
			renderHomeBody();
			if (!hadFocus) return;
			var again = null;
			var all = homeView.querySelectorAll('button, [role="button"], input, select, textarea');
			for (var i = 0; i < all.length; i++) {
				if ((all[i].textContent || '').trim() === hadFocus) { again = all[i]; break; }
			}
			if (again && again.focus) { try { again.focus(); } catch (e) { /* not focusable now */ } }
		}

		/// The status rows that are settings, not states (STATUS-REVIEW, D-20261015-15):
		/// models, money, Pro, tools, permissions, version, storage and sync. They left the
		/// rail for the foot of Settings home. The NODE moves, ids and all, so every painter
		/// that fills them by id goes on working wherever they stand.
		var statusDetailEl = null;
		function mountStatusDetail() {
			var d = statusDetailEl || (statusDetailEl = document.getElementById('astat-detail'));
			if (!d || !homeView) return;
			homeView.appendChild(el('div', 'admin-sec', tOr('home.sec_status', 'This device')));
			d.hidden = false;
			d.classList.add('astat-in-settings');
			homeView.appendChild(d);
		}
		function renderHomeBody() {
			renderHomeBodyInner();
			mountStatusDetail();
			// Settings opens on the weekly stop and six doors (D-20261024-16): settingsgroups.js
			// regroups what was just drawn, by intent.
			if (window.DaimondSettingsGroups) DaimondSettingsGroups.apply(homeView, titleEl);
		}
		function renderHomeBodyInner() {
			if (!homeView) return;
			homeView.innerHTML = '';
			var idOn = window.DaimondIdentity && DaimondIdentity.exists() && DaimondIdentity.isUnlocked();

			// Daimond cannot run without a model, so say so where it can be fixed.
			if (!cfgReady(pg.cfg)) {
				var cta = document.createElement('button');
				cta.className = 'admin-cta';
				cta.textContent = t('home.connect_model');
				cta.addEventListener('click', function () { openSettings(''); });
				homeView.appendChild(cta);
				homeView.appendChild(el('div', 'admin-note', t('home.connect_note')));
			}

			if (!idOn) {
				// An account that exists but is locked is not an account that
				// needs creating — the unlock card is already over the app.
				if (window.DaimondIdentity && DaimondIdentity.exists()) {
					homeView.appendChild(el('div', 'admin-note', t('home.locked')));
				} else if (identityAvailable()) {
					homeView.appendChild(el('div', 'admin-sec', t('home.sec_account')));
					item(t('home.create_account'), function () { showIdentity('create'); });
					homeView.appendChild(el('div', 'admin-note', t('home.account_note')));
				}
				// Offered here too, and not only to an account holder: the machine hand
				// and its git toolkit work with no identity at all, and a person who has
				// skipped the account screen still has repositories. What DIFFERS without
				// an account is only how long the token lasts, and the panel says so.
				// The run settings likewise: none of them needs an account.
				runSection();
				pushSection();
				return;
			}

			homeView.appendChild(el('div', 'admin-sec', t('home.sec_account')));
			var fp = DaimondIdentity.fingerprint();
			if (fp) {
				// The fingerprint is a hash of the PUBLIC key, so it is safe to hand
				// on -- and handing it on is the point: it is what tells a support
				// message which account it is about. The value moves into a span of
				// its own so the button can sit beside it without the ellipsis
				// eating it on a narrow rail.
				var f = el('div', 'account-fp');
				f.title = t('home.fingerprint');
				f.appendChild(el('span', 'account-fp-val', fp));
				f.appendChild(idCopyBtn(tOr('copy.what_fingerprint',
					'your account fingerprint'), fp));
				homeView.appendChild(f);
			}
			// The account's PUBLIC name, beside the fingerprint because those are the
			// two things about this account that a stranger can be shown. Drawn only
			// when there is one: the gateway mints it, and a browser that has never
			// reached a gateway has nothing to name.
			var hdl = accountHandle();
			if (hdl) {
				var hrow = el('div', 'account-fp');
				hrow.id = 'account-handle';
				hrow.title = tOr('home.handle_help',
					'Your public handle: the name other people see, the same on every '
						+ 'device of this account.');
				hrow.appendChild(el('span', 'account-fp-val', hdl));
				hrow.appendChild(idCopyBtn(tOr('copy.what_handle', 'your public handle'), hdl));
				homeView.appendChild(hrow);
			}
			item(t('home.change_name'),       doRename);
			// Beside "Change name…" because a user meets the two as one question --
			// what am I called -- and the answers differ: the line above labels THIS
			// DEVICE's keypair and is seen by nobody, while this is the account's public
			// name. `DaimondSync.claimHandle` was written, and its four refusals
			// translated into eight languages, with no caller anywhere: an account was
			// minted `bright-finch-5m5m` and kept it for ever.
			//
			// Offered whether or not a name has arrived yet. A control that appears only
			// once the gateway has answered is a control the user cannot find at the
			// moment they want it, and the refusal for an unreachable gateway is one of
			// the four sentences already written.
			if (window.DaimondSync && DaimondSync.claimHandle) {
				var hb = item(tOr('home.change_handle', 'Change public handle…'), doChangeHandle);
				hb.id = 'admin-change-handle';
			}
			item(t('home.change_passphrase'), doChangePassphrase);
			// A passkey unlocks this device without the passphrase. Offer to add one
			// only where the platform supports it; offer to remove one once enrolled.
			if (window.DaimondPasskey) {
				if (DaimondPasskey.isEnrolled()) {
					item(t('home.remove_passkey'), doRemovePasskey);
				} else {
					var pk = item(t('home.add_passkey'), doAddPasskey);
					pk.style.display = 'none';
					DaimondPasskey.available().then(function (ok) { if (ok) pk.style.display = ''; }).catch(function () {});
				}
			}
			item(t('home.export_backup'), doExport);
			item(t('home.import_backup'), doImport);

			// How many devices this account is on. A question a local-first app
			// owes an answer to, and one nothing else on screen can answer: a
			// linked device holds the same keypair, so the gateway sees one user
			// and the pairing itself left no record anywhere.
			renderDevices();

			// The operator console, for the handful of accounts that hold a role.
			renderConsoleLink();

			// What each kind of agent is told, which is the user's to change.
			//
			// Only buttons here: this drawer is narrow, and a system prompt is a
			// page of prose. Each opens its file in the Doc panel, which is where
			// the app already edits text, with the room to do it in.
			homeView.appendChild(el('div', 'admin-sec', t('home.sec_prompts')));
			Prompts.roles.forEach(function (r) {
				// The role label is substituted as-is: lower-casing it mangled the
				// product noun ("diamond conductor") in every language at once,
				// and a locale table cannot defend itself against a transform.
				var b = item(t('home.edit_prompt', { role: t(r.label) }), function () {
					closeAdmin();                     // the Doc panel is behind this drawer
					Prompts.edit(r.id);
				});
				b.title = t(r.blurb) + ' ' + t('home.prompt_opens', { path: Prompts.path(r.id) });
			});

			runSection();
			// Where a push goes, and the token it goes with.
			pushSection();

			// The email doorbell and the posting name live in Social ▸ Settings,
			// which no longer has a chip of its own: Feed took the sixth slot on
			// 2026-09-15 and the admin drawer is where this app keeps settings, so this row
			// is the door. The view is unmoved -- js/improve.js's `drawSettings`
			// still draws all of it and still calls `DaimondDoorbell.mount` with its
			// own host -- and this drawer keeps none of it.
			if (window.DaimondSocial && DaimondSocial.open) {
				var ssb = item(tOr('home.social_settings', 'Social settings…'), function () {
					closeAdmin();				// the panel is behind this drawer
					DaimondSocial.open('settings');
				});
				ssb.id = 'admin-social-settings';
				ssb.title = tOr('home.social_settings_help',
					'The posting name this device writes under, and the email doorbell.');
			}

			// ── Syncing, and the app's own trail ──────────────────
			//
			// HERE, in the panel a person actually opens, and not only in the
			// Models view. Both of these were put behind the settings form first
			// and the user could not find either — the sync switch at the moment
			// they had been asked to turn syncing off, which made it useless
			// exactly when it mattered. A control nobody can find is a control
			// that does not exist.
			homeView.appendChild(el('div', 'admin-sec', tOr('home.sec_sync', 'Syncing and diagnostics')));
			// ── "Something went wrong": the Feedback surface's half of D-20260920-02 ──
			//
			// The other tap of the same one-tap action the error toast offers
			// (`errorToastWithReport`), for the person who dismissed that toast, or
			// whose bug did not throw loudly enough to raise one, and wants to say so
			// from here instead. Always visible — unlike the Diagnostics toggle below,
			// this needs no opt-in to press, because pressing it IS the opt-in
			// (`DaimondSupport` asks consent itself, once per account, the first time).
			if (window.DaimondSupport) {
				var reportOut = el('div', 'admin-note', '');
				reportOut.hidden = true;
				var reportBtn = item(tOr('settings.support_report', 'Something went wrong? Send a report'), function () {
					reportBtn.disabled = true;
					reportOut.hidden = false;
					DaimondSupport.report('settings', function (said) {
						reportOut.textContent = said;
						reportBtn.disabled = false;
					});
				});
				reportBtn.title = tOr('settings.support_help',
					'Sends the app’s recent activity log — event names, ids, counts and a '
						+ 'clock, never your messages, files or keys — to the Daimond team. Asked '
						+ 'to agree once; every linked device remembers the answer.');
				homeView.appendChild(reportOut);
			}
			if (window.DaimondSafe) {
				var syncing = !DaimondSafe.on();
				var sb = item(syncing
					? tOr('safe.turn_off', 'Start without syncing')
					: tOr('safe.turn_on', 'Turn syncing back on'), function () {
					DaimondSafe.set(syncing, 'user');       // syncing → we are turning it OFF
					location.reload();
				});
				// The full account of what stopping does rides on the control's
				// hover, so the on-screen line stays a one-clause label.
				sb.title = tOr('settings.sync_help',
					'Stopping is immediate and loses nothing; your work stays on this '
						+ 'device and this device stops reaching your others.');
				// Said only for the state that needs saying: syncing is the default.
				if (!syncing) {
					homeView.appendChild(el('div', 'admin-note',
						tOr('settings.sync_off_note', 'Not syncing — your work stays here.')));
				}
			}
			if (window.DaimondTrail) {
				var trailOut = el('div', 'admin-note', '');
				trailOut.style.whiteSpace = 'pre-wrap';
				trailOut.style.userSelect = 'text';
				trailOut.hidden = true;
				var tb = item(tOr('settings.trail_copy', 'Copy the app’s own trail'), function () {
					// A SECOND press puts it away again. Showing the trail used to be a
					// one-way door: the text appeared, the button relabelled itself, and
					// nothing on the screen returned it to how it was -- so a diagnostic
					// somebody opened once sat over the panel for the rest of the session.
					// `verify_reversible` calls that a trap and it is right.
					if (!trailOut.hidden) {
						trailOut.hidden = true;
						tb.textContent = tOr('settings.trail_copy', 'Copy the app’s own trail');
						return;
					}
					var text = '';
					try { text = DaimondTrail.text(); } catch (e) { text = ''; }
					// SHOWN as well as copied. The clipboard is refused often enough
					// on a phone that a button which only copies is one that
					// sometimes does nothing and reports success.
					trailOut.textContent = text || tOr('settings.trail_empty', 'Nothing recorded yet.');
					trailOut.hidden = false;
					var done = function () { tb.textContent = tOr('trail.copied', 'Copied'); };
					if (text && navigator.clipboard && navigator.clipboard.writeText) {
						navigator.clipboard.writeText(text).then(done, function () { fallback(text, done); });
					} else if (text) { fallback(text, done); }
				});
				// The detail -- what the trail does and does not carry -- rides on the
				// button's hover; the note is a one-line label.
				tb.title = tOr('settings.trail_help',
					'Event names and a clock only: no keys, no message text, nothing from '
						+ 'your files. Safe to paste into a bug report.');
				homeView.appendChild(trailOut);
				homeView.appendChild(el('div', 'admin-note',
					tOr('settings.trail_note', 'A safe-to-share log of what Daimond last did.')));
			}

			// ── Diagnostics: the OPT-IN, richer sync/apply trail ─────────
			//
			// OFF by default and per-device (www/js/diag.js). When off, the app
			// records nothing extra and nothing can leave the device; the switch
			// here is the only thing that turns it on. When on, this device keeps a
			// 500-event ring of its sync/apply DECISIONS -- which chats a parcel
			// carried, which the merge kept, skipped, removed or resurrected, how a
			// hand-off moved -- readable in a panel below and, on request, shareable
			// with the operator so an iPhone's behaviour becomes visible server-side.
			// The whole point is the bug no console on a phone can show.
			if (window.DaimondDiag) {
				homeView.appendChild(el('div', 'admin-sec',
					tOr('home.sec_diag', 'Diagnostics')));
				var diagOn = DaimondDiag.on();
				var diagPanel = el('div', '', '');
				diagPanel.style.marginTop = '8px';
				diagPanel.hidden = true;
				var shareNote = el('div', 'admin-note',
					tOr('settings.diag_share_note',
						'Sharing sends this device’s diagnostic log — chat ids, versions and '
							+ 'counts, never message text — to the Daimond team.'));
				shareNote.hidden = !diagOn;

				function paintDiagPanel() {
					try {
						DaimondDiag.renderPanel(diagPanel, {
							device:     selfDeviceId(),
							deviceName: deviceName(),
							version:    (window.DaimondSync && DaimondSync.version) ? DaimondSync.version() : null,
							chats:      Array.isArray(pg.chats) ? pg.chats.length : null,
							locked:     !(window.DaimondIdentity && DaimondIdentity.isUnlocked && DaimondIdentity.isUnlocked()),
							build:      (window.DaimondTrail && DaimondTrail.lastBuild && DaimondTrail.lastBuild()) || '',
						});
					} catch (e) { diagPanel.textContent = ''; }
				}

				var toggleBtn, panelBtn, shareBtn, retryBtn, share;
				toggleBtn = item('', function () {
					DaimondDiag.set(!DaimondDiag.on(), 'settings');
					var now = DaimondDiag.on();
					toggleBtn.textContent = now
						? tOr('settings.diag_off', 'Turn diagnostics off')
						: tOr('settings.diag_on', 'Turn diagnostics on');
					panelBtn.hidden = !now;
					shareBtn.hidden = !now;
					retryBtn.hidden = true;
					shareNote.hidden = !now;
					if (!now) { diagPanel.hidden = true; diagPanel.textContent = ''; }
				});
				toggleBtn.textContent = diagOn
					? tOr('settings.diag_off', 'Turn diagnostics off')
					: tOr('settings.diag_on', 'Turn diagnostics on');
				toggleBtn.title = tOr('settings.diag_help',
					'Off by default. When on, this device records its sync decisions so a '
						+ 'problem that only shows on this device can be seen. No message text, '
						+ 'no keys, no file contents — chat ids, versions and counts only.');

				// The panel: a second press puts it away, mirroring the trail button
				// so a diagnostic opened once does not sit over the panel for good.
				panelBtn = item(tOr('settings.diag_panel', 'Open debug panel'), function () {
					if (!diagPanel.hidden) { diagPanel.hidden = true; return; }
					paintDiagPanel();
					diagPanel.hidden = false;
				});
				panelBtn.hidden = !diagOn;

				// A share that does not land reads "Not sent: {reason}", with Retry beside it.
				shareBtn = item(tOr('settings.diag_share', 'Share diagnostic log'), function () { share(); });
				retryBtn = item('', function () { share(); });
				share = DaimondDiag.shareControl(shareBtn, retryBtn);
				shareBtn.hidden = !diagOn;

				homeView.appendChild(diagPanel);
				homeView.appendChild(shareNote);
			}

			// ── TRAINING WHEELS — remove after beta. ─────────────────────
			//
			// "Share all data for debugging": the temporary, owner-requested debug
			// aid. OFF by default and per-device. When on, this device ships its
			// DECRYPTED diagnostics -- the whole lot -- to the developer, with the
			// provider key and master key reduced to fingerprints, and a prominent
			// header indicator warns while it is on. The switch is here; everything
			// else lives in www/js/debugshare.js and lifts out in one pass. See its
			// header. Guarded on the global so a build without the script is inert.
			if (window.DEBUG_SHARE) {
				homeView.appendChild(el('div', 'admin-sec',
					tOr('home.sec_debugshare', 'Debug data sharing')));
				var dsOn = DEBUG_SHARE.isOn();
				var dsNote = el('div', 'admin-note',
					tOr('settings.debugshare_note',
						'Beta training-wheel, to be removed. When on, this shares ALL your '
							+ 'Daimond data — your chats, costs, devices and settings — with the '
							+ 'developer for debugging. Your keys are never shared. Off by default.'));
				var dsBtn = item('', function () {
					DEBUG_SHARE.setEnabled(!DEBUG_SHARE.isOn());
					var now = DEBUG_SHARE.isOn();
					dsBtn.textContent = now
						? tOr('settings.debugshare_off', 'Stop sharing data for debugging')
						: tOr('settings.debugshare_on', 'Share all data for debugging (temporary)');
				}, true);
				dsBtn.textContent = dsOn
					? tOr('settings.debugshare_off', 'Stop sharing data for debugging')
					: tOr('settings.debugshare_on', 'Share all data for debugging (temporary)');
				dsBtn.title = tOr('settings.debugshare_help',
					'Beta only, and temporary. When on, everything on this device — chats, '
						+ 'costs, devices, settings — is shared with the developer to debug a '
						+ 'problem. Your provider key and passphrase key are never shared.');
				homeView.appendChild(dsNote);
			}

			// Lens screenshots (D-20261006-14): the owner's own devices only, off until he turns it
			// on here, per device and never synced. Everything else is www/js/lensshot.js.
			if (window.DaimondLensShot && consoleRole === 'owner') {
				homeView.appendChild(el('div', 'admin-sec', t('home.sec_lens')));
				var lsLabel = function () {
					return DaimondLensShot.enabled() ? t('settings.lensshot_off') : t('settings.lensshot_on');
				};
				var lsBtn = item(lsLabel(), function () {
					DaimondLensShot.setEnabled(!DaimondLensShot.enabled());
					lsBtn.textContent = lsLabel();
				});
				lsBtn.dataset.lensshot = '1';
				lsBtn.title = t('settings.lensshot_help');
			}

			// Several people can share this browser, each with their own account. Switching locks
			// this one first (its keys are forgotten), then reloads into the other.
			if (window.DaimondAccounts) {
				homeView.appendChild(el('div', 'admin-sec', t('home.sec_accounts')));
				var accts = DaimondAccounts.list();
				var cur = DaimondAccounts.current();
				accts.forEach(function (a) {
					if (a.id === cur) return;
					item(t('home.switch_to', { name: a.name || t('home.unnamed_account') }),
						function () { switchAccount(a.id); });
				});
				item(t('home.add_account'), addAccount);
			}

			// Lock beside Log out: the only difference is the session on the gateway
			// side, which Lock keeps and Log out ends (see `lockApp` above).
			item(t('home.lock'),            function () { lockApp(true); });
			item(t('home.log_out'),         function () { lockApp(false); });
			item(t('identity.forget'),      forgetIdentity, true);

			function item(label, fn, danger) {
				var b = document.createElement('button');
				b.className = 'admin-item' + (danger ? ' danger' : '');
				b.textContent = label;
				b.addEventListener('click', fn);
				homeView.appendChild(b);
				return b;
			}

			/// The ways through to the settings that are not models: how far a turn may run,
			/// what the agent searches with, and the folders a hand may reach. Folders is
			/// offered only once a hand has offered one, as its rows always were.
			function runSection() {
				homeView.appendChild(el('div', 'admin-sec', t('home.sec_running')));
				var lb = item(t('home.limits'), limits);
				lb.id = 'admin-open-limits';
				lb.title = t('home.limits_help');
				var sb = item(t('home.search'), search);
				sb.id = 'admin-open-search';
				sb.title = t('home.search_help');
				if (TermRootRow && TermRootRow.offers()) {
					var fb = item(t('home.folders'), folders);
					fb.id = 'admin-open-folders';
					fb.title = t('home.folders_help');
				}
			}

			/// The way through to the push credential, with the host it currently
			/// reaches written on the line.
			///
			/// Read from the ENGINE and not from what the page last saved, because those
			/// two differ in exactly the case this whole arrangement exists for: a reload
			/// empties the engine's copy, and a drawer drawn from storage would say a
			/// push was configured while every push was being refused.
			function pushSection() {
				homeView.appendChild(el('div', 'admin-sec', t('home.sec_push')));
				var held = pushHostHeld();
				var b = item(held ? t('home.push_to', { host: held }) : t('home.push_setup'),
					function () { push(); });
				b.title = t('home.push_help');
			}
		}

		/// The devices that sync this account: this one first, then the rest by
		/// how recently they were seen.
		///
		/// A row takes a name, and can be taken off the list. The second control
		/// was withheld for a long time on the reasoning that pairing hands the
		/// other device the same keypair, so nothing here could enforce a
		/// revocation and a button pretending to would be worse than none. That
		/// reasoning holds and the button does not claim otherwise: what it fixes
		/// is a list filling with machines the user has not owned for a year, which
		/// is what the author asked for. The short id suffix stays even for a named
		/// device: it is what tells two lines apart while they are both still
		/// called "Chrome on macOS".
		function renderDevices() {
			// BEFORE the roster is read, not after. A nominee stranded on a superseded id
			// follows the live machine that replaced it and the superseded lines are swept
			// here; reading `reg` first drew every line this sweep was about to remove one
			// more time, so a pruned ghost reappeared until the next redraw.
			try { reconcileRoster(); } catch (e) { /* best-effort */ }
			var reg = collectDevices();		// reading it is also how this device joins it
			var self = deviceId();
			var nominee = nominatedDeviceId();	// the account's always-on runner, or ''
			// Who is beating now, so the list can mark a line that is no longer here and a
			// GHOST a live device has replaced. A live device NOT yet synced into the
			// roster still gets a row -- from its beat -- so the owner can star the machine
			// that is here even before its line has propagated (the disjoint-roster case).
			var presence = (window.DaimondPresence && DaimondPresence.snapshot()) || {};
			var live = rosterLiveness(reg, presence, nominee, Date.now(),
				(window.DaimondPeer && DaimondPeer.DISPATCH_FRESH_MS));
			Object.keys(presence).forEach(function (id) {
				if (reg[id] || !live.live[id]) return;
				reg[id] = { name: String(presence[id].name || ''), label: '',
					created: 0, namedAt: 0, seen: presenceSeenMs(presence[id]) };
			});
			// WHEN A ROW WILL SAY IT WAS LAST HERE -- computed once, because it is also
			// what the list is ORDERED by. It was ordered by the roster's `seen` and
			// worded from the presence beat, and those two disagree for any device that
			// is awake with nothing to say: the owner's list read "just now / 2m ago /
			// 1m ago" down the page (trace, 2026-09-13). One source for both.
			var whenOf = function (idv) {
				var w = (live.live[idv] && presence[idv]) ? presenceSeenMs(presence[idv]) : 0;
				return w || (reg[idv] ? ms(reg[idv].seen) : 0);
			};
			var ids = Object.keys(reg).sort(function (a, b) {
				var sa = a === self ? 1 : 0, sb = b === self ? 1 : 0;
				if (sa !== sb) return sb - sa;
				return whenOf(b) - whenOf(a);
			});
			// ONE ROW PER DEVICE, and a pre-migration SHADOW is not a device.
			//
			// A machine that has not reloaded since the id spaces were joined beats
			// presence under its identity id while its roster line is still keyed by the
			// legacy one, and nothing can join the two until that machine runs
			// `migrateLegacySelfLine` for itself. So it arrives as TWO lines: the live one
			// from its beat, carrying no build, and the dead one from the roster, carrying
			// the build and therefore the "reload me" tag -- pinned, in other words, on
			// the half of the pair that cannot be reloaded. That is what the owner met on
			// 2026-09-13 and called indecipherable.
			//
			// Nothing mints a legacy-width id any more, so a legacy line that is not
			// beating is never a device in its own right: the machine is either here under
			// its identity id or gone. It is still READ -- it is the only thing that knows
			// a build a peer has not re-synced yet, and the skew line below names it by
			// that -- but it is not a row. A line a migration record calls superseded is
			// already swept by `reconcileRoster` above; this is the case with no record,
			// because the device that would have written one has not reloaded.
			var shadow = {};
			ids.forEach(function (idv) {
				if (idv !== self && LEGACY_ID_RE.test(idv) && !live.live[idv]) shadow[idv] = true;
			});
			ids = ids.filter(function (idv) { return !shadow[idv]; });
			if (!ids.length) return;
			// The caveat that used to sit under the list as a paragraph -- what the
			// list is, and that nothing here signs a device out -- rides on the
			// header's hover now, and the guide's sync page carries the rest. The
			// rows below are the controls; the prose is one `title` away.
			var devSec = el('div', 'admin-sec', t('home.sec_devices'));
			devSec.title = t('devices.note');
			homeView.appendChild(devSec);
			// The build the fleet SHOULD be on, and each device's known build. THIS
			// device is read from the live build id (always known); a peer from its
			// live presence beat (once the gateway relays it) or, failing that, its
			// roster line, which survives the peer being offline. '' = unknown, and is
			// never read as stale -- a fleet whose gateway does not relay build and
			// whose peers have not re-synced simply shows no skew rather than a false one.
			var curBuild = fleetCurrentBuild();
			var buildOf  = function (idv) {
				if (idv === self) return buildId();
				return ((presence[idv] && presence[idv].build) || (reg[idv] && reg[idv].build) || '');
			};
			// What a device is CALLED, wherever this function needs to say so. The user's
			// own name wins; failing that a LIVE device's own broadcast label -- what it
			// beats under -- is preferred over the stored `name`, which is a generic
			// self-description ("Chrome on Linux") two machines derive identically.
			var shownName = function (idv) {
				var dv = reg[idv] || {};
				var liveLabel = (live.live[idv] && presence[idv]) ? String(presence[idv].name || '') : '';
				return dv.label || liveLabel || dv.name || t('devices.unknown');
			};
			// WHICH devices are behind, by name. "Your devices are on 2 different builds.
			// Reload the older ones to update." is true and useless: the owner still had to
			// compare seven-character prefixes across three machines to find out which one
			// to reload, and reported exactly that. Read across the WHOLE roster and not
			// just the rows, because a shadow line (above) is the only thing that knows the
			// build of a peer that has not re-synced -- which is the device that needs it.
			var olderNames = [], olderBuild = '', seenName = {};
			Object.keys(reg).forEach(function (idv) {
				var b = buildOf(idv);
				if (!b || !curBuild || b === curBuild) return;
				var nm = shownName(idv);
				if (seenName[nm]) return;
				seenName[nm] = true;
				olderNames.push(nm);
				if (!olderBuild) olderBuild = b;
			});
			if (olderNames.length) {
				var skew = el('div', 'device-skew', olderNames.length === 1
					? tOr('devices.skew_one', '{name} is on build {id} — reload it.',
						{ name: olderNames[0], id: olderBuild.slice(0, 7) })
					: tOr('devices.skew_many', '{names} are on older builds — reload them.',
						{ names: olderNames.join(', ') }));
				skew.setAttribute('role', 'status');
				homeView.appendChild(skew);
			}
			ids.forEach(function (id) {
				var d = reg[id], r = el('div', 'device-row');
				// A line not beating now reads muted (stale); one a live device has
				// replaced under a new id wears a "replaced" tag and is safe to remove.
				var isStale = id !== self && !!live.stale[id];
				// Never this device. The row the user is standing on cannot have been
				// replaced by anything, and saying so of it was the loudest symptom of the
				// two id spaces: the owner's own line wore "REPLACED" beside a prune button
				// that refused to act on it.
				var isGhost = id !== self && !!live.ghost[id];
				if (isStale) r.classList.add('is-stale');
				if (isGhost) r.classList.add('is-ghost');
				// What the row is CALLED -- see `shownName`, which the skew line above reads
				// too. Display only; nothing is keyed on a name any more.
				var shown = shownName(id);
				var nameEl = el('span', 'device-name', shown);
				// The row shortens this with CSS ellipsis, which is fine on screen and
				// says nothing to a mouse that never hovers or a screen reader that
				// never reads a `title` at all -- so the full name goes on both.
				nameEl.title = shown;
				nameEl.setAttribute('aria-label', shown);
				r.appendChild(nameEl);
				// V10 (layout_contract.md, D-20260929-03): an explicit grid, "name copy
				// rename" / "ctl ctl ctl" / "meta meta meta", so the row's shape never
				// depends on how long the name is. `.device-id`, `.device-when` and
				// `.device-build` -- and the ghost/nominee/old-build badges beside them
				// -- share the meta line.
				var metaWrap = el('div', 'device-meta');
				metaWrap.appendChild(el('span', 'device-id', id.slice(-4)));
				// WHEN IT WAS LAST HERE, from the BEAT where there is one -- `whenOf`, which
				// the ordering above reads as well, so the list cannot be sorted by one stamp
				// and worded from another. The roster's `seen` travels only on a parcel that
				// had something else to say (see `compareKey` in sync.js), so a device that is
				// beating with no news of its own would read "2 days ago" while sitting there
				// awake; the roster stamp is the durable fallback for a device that is not
				// beating, which is the only row the words are really about.
				var whenMs = whenOf(id);
				metaWrap.appendChild(el('span', 'device-when',
					id === self ? t('devices.this_device') : relTime(whenMs)));
				// The build this device is running, shown on every row so the fleet's
				// build spread is legible at a glance -- and flagged when it is a KNOWN
				// build behind what this device knows is current, which is the mixed-build
				// hand-off failure made visible. Unknown ('') shows nothing and never flags.
				var rowBuild = buildOf(id);
				if (rowBuild) {
					var bEl = el('span', 'device-build', tOr('devices.build', 'build {id}',
						{ id: rowBuild.slice(0, 7) }));
					bEl.title = rowBuild;
					metaWrap.appendChild(bEl);
					if (curBuild && rowBuild !== curBuild) {
						r.classList.add('is-oldbuild');
						// Two words, not six: the chip shares a line with a name, an id, a
						// stamp and four controls, and "on an old build — reload" was a third
						// of what pushed a row 450px wide into a 380px drawer. The sentence
						// it used to be is on the hover and in the skew line above.
						var ob = el('span', 'device-oldbuild',
							tOr('devices.old_build', 'old build'));
						ob.title = tOr('devices.old_build_aria',
							'This device is running an older build than yours. Reload it to update.');
						metaWrap.appendChild(ob);
					}
				}
				// A ghost is a machine that is here now under a different id, so the owner
				// can tell it from one that is merely switched off and safely remove it.
				if (isGhost) {
					var g = el('span', 'device-ghost', tOr('devices.replaced', 'replaced'));
					g.title = tOr('devices.replaced_aria',
						'A device that is here now has taken this one’s place. It is safe to remove.');
					metaWrap.appendChild(g);
				}
				// The nominee wears a small badge, so the one always-on runner is plain
				// at a glance without reading every ✩ button.
				if (nominee && id === nominee) {
					var badge = el('span', 'device-nominee', t('devices.nominee'));
					badge.title = t('devices.nominee_aria', { name: shown });
					metaWrap.appendChild(badge);
				}
				r.appendChild(metaWrap);
				// The row shows the last four characters, which is all that is
				// needed to tell two lines apart; the button copies the WHOLE id,
				// which is what a support message or a sync question actually
				// needs. The id is a random number this device wrote down for this
				// account -- it authorises nothing, and it is already in the roster
				// every paired device holds.
				r.appendChild(idCopyBtn(tOr('copy.what_device', 'the id of {name}',
					{ name: shown }), id));
				// The nominate star and the stay-unlocked switch share the row's
				// `ctl` line (V10).
				var ctlWrap = el('div', 'device-ctl');
				// Nominate this device the always-on runner, or clear it. A single
				// scalar per account, so nominating one clears any other; filled =
				// the nominee, hollow = not, the same star drawn two ways rather
				// than the ✭/✩ glyph pair a size and a colour of their own could
				// not be brought level with the icon buttons beside it (§10). Every
				// row, this device included -- a desktop naming itself the runner
				// is the common case.
				var nom = document.createElement('button');
				var isNominee = !!(nominee && id === nominee);
				nom.className = 'device-nominate' + (isNominee ? ' is-nominee' : '');
				nom.type = 'button';
				nom.innerHTML = '<svg class="ic" viewBox="0 0 24 24" aria-hidden="true">' +
					'<path d="M12 3l2.6 5.35 5.9.86-4.27 4.16 1.01 5.88L12 16.9l-5.24 2.75 1.01-5.88L3.5 9.21l5.9-.86L12 3z"/></svg>';
				nom.title = isNominee ? t('devices.unnominate_aria', { name: shown })
					: t('devices.nominate_aria', { name: shown });
				nom.setAttribute('aria-label', nom.title);
				nom.setAttribute('aria-pressed', isNominee ? 'true' : 'false');
				nom.addEventListener('click', function () { setNominee(isNominee ? '' : id); });
				ctlWrap.appendChild(nom);
				// This device's own row only -- the setting is per-tab, held in THIS
				// browser's storage, so a control on any other row would change nothing
				// there and only look like it worked. Off by default on a phone and on
				// by default on a desktop; see the note above `stayUnlocked` in identity.js.
				if (id === self && window.DaimondIdentity && DaimondIdentity.setStayUnlocked) {
					var isStay = !!(DaimondIdentity.stayUnlocked && DaimondIdentity.stayUnlocked());
					// A LABELLED TOGGLE, not the icon-only padlock this used to be with its
					// meaning folded into a 54-word title (audit 2026-09-15, ADM-02 /
					// annoyance 6). The label is the visible text now, so the title that
					// used to carry it is gone rather than repeated (GEN-05) -- `role` and
					// `aria-checked` are what say the rest to a reader who cannot see it.
					var stay = document.createElement('button');
					stay.className = 'device-stay' + (isStay ? ' is-on' : '');
					stay.type = 'button';
					stay.setAttribute('role', 'switch');
					stay.setAttribute('aria-checked', isStay ? 'true' : 'false');
					var stayIcon = el('span', 'device-stay-icon');	// padlock drawn by .device-stay(.is-on)
					stayIcon.setAttribute('aria-hidden', 'true');
					var stayLabel = el('span', 'device-stay-label', t('devices.stay_unlocked_label'));
					stay.appendChild(stayIcon);
					stay.appendChild(stayLabel);
					stay.addEventListener('click', function () {
						DaimondIdentity.setStayUnlocked(!isStay);
						renderHome();
					});
					ctlWrap.appendChild(stay);
				}
				r.appendChild(ctlWrap);
				// The rename pencil and the remove cross share the row's `rename`
				// line (V10).
				var actsWrap = el('div', 'device-acts');
				// Every row, not only this device's: the name carries a stamp of
				// its own, so one typed here reaches the device it names.
				var b = document.createElement('button');
				b.className = 'device-rename';
				b.type = 'button';
				// The same outline pencil the file row's Edit action draws
				// (D-20260929-03 §10), in place of a text glyph a size and a
				// colour of its own could not be brought level with the icon
				// buttons beside it.
				b.innerHTML = ACTION_ICONS.edit;
				b.title = t('devices.rename_aria', { name: shown });
				b.setAttribute('aria-label', b.title);
				b.addEventListener('click', function () { askDeviceName(id, shown); });
				actsWrap.appendChild(b);
				// Not on this device's own row. Removing the line the app is
				// writing would only re-mint it on the next collect, so the
				// control would do nothing and look broken.
				if (id !== self) {
					var rm = document.createElement('button');
					rm.className = 'device-remove';
					rm.type = 'button';
					rm.textContent = '✕';
					rm.title = tOr('devices.remove_aria', 'Remove {name}', { name: shown });
					rm.setAttribute('aria-label', rm.title);
					rm.addEventListener('click', function () { askRemoveDevice(id, shown); });
					actsWrap.appendChild(rm);
				}
				r.appendChild(actsWrap);
				homeView.appendChild(r);
			});
			// One tap to clear every replaced device at once, shown only when there is a
			// ghost to clear. Each removal tombstones the line, so it stays gone across
			// the next sync round rather than unioning straight back (the add-only-merge
			// resurrection the whole reconcile is written to stop).
			var ghosts = Object.keys(live.ghost).filter(function (gid) { return gid !== self; });
			if (ghosts.length) {
				var prune = document.createElement('button');
				prune.className = 'device-prune-all';
				prune.type = 'button';
				prune.textContent = ghosts.length === 1
					? tOr('devices.prune_one', 'Remove the replaced device')
					: tOr('devices.prune_many', 'Remove {n} replaced devices', { n: ghosts.length });
				prune.addEventListener('click', function () {
					ghosts.forEach(function (gid) { try { removeDevice(gid); } catch (e) { /* best effort */ } });
					if (window.DaimondSync && DaimondSync.nudge) {
						try { DaimondSync.nudge(); } catch (e) { /* not syncing */ }
					}
					renderHome();
				});
				homeView.appendChild(prune);
			}
			// A lone device keeps its one-line note: it says something the empty
			// list cannot. A multi-device list speaks for itself, so the prose that
			// once stacked under it is gone -- the caveat is on the header hover, the
			// ✩ is explained by its own hover, and the guide's sync page holds the
			// rest.
			if (ids.length === 1) {
				homeView.appendChild(el('div', 'admin-note', t('devices.only_this')));
			}
			if (window.DaimondPairing && DaimondPairing.runner) runnerCodeRow(homeView);
			if (window.DaimondGateway && DaimondGateway.gwFetch) runnerMintRow(homeView);
		}

		/// Name a device the always-on runner, or clear the nomination with ''. Pushes
		/// the choice to the other devices at once (it is an account fact) and redraws.
		function setNominee(id) {
			// This device's own ✭ puts the runner question at the press, and the answer
			// decides the nomination: no nominates nothing. Left to runner.js's
			// fifteen-second poll, the dialog arrived up to fifteen seconds later over
			// whatever screen was up by then (UNBLOCK-24 r3). A nomination made on
			// another device keeps the polled ask, which is the case the poll is for.
			if (id && id === deviceId() && window.DaimondRunner && DaimondRunner.ask) {
				DaimondRunner.ask().then(function (yes) { if (yes) saveNominee(id); },
					function () { /* no answer, no nomination */ });
				return;
			}
			saveNominee(id);
		}

		function saveNominee(id) {
			// A star the contract refuses is SAID. It used to redraw the same hollow
			// star and nothing else, which is how a runner's refused id went unseen
			// (STARFIX, UNBLOCK-36).
			if (!nominateDevice(id)) {
				toast(t('devices.nominate_refused'), true);
				return;
			}
			if (window.DaimondSync && DaimondSync.nudge) {
				try { DaimondSync.nudge(); } catch (e) { /* not syncing */ }
			}
			renderHome();
		}

		/// A way through to the operator console, for accounts that hold a role.
		///
		/// Shown to role-holders ONLY, and the reason is not that the console is
		/// secret. It is served at a guessable path, its script is public, and the
		/// gate is decided server-side by the gateway; a link changes who bothers
		/// to look, not who gets in. What a link for everybody WOULD do is teach
		/// every user the shape of a phishing script -- "Daimond has an admin
		/// console, and the way in is to copy your account id out of a card and
		/// send it to someone" -- and put a door in front of the overwhelming
		/// majority that they cannot open, which this app's own history says gets
		/// read as a fault rather than as a boundary.
		///
		/// The role is asked for lazily, when the drawer opens, so an account that
		/// will never hold one pays nothing at launch. The answer decides a link
		/// and nothing else: every action inside the console is authorised by the
		/// gateway on its own, and a client that lied to itself here would gain
		/// exactly one useless hyperlink.
		// What the gateway last said about this account, and whether that answer
		// is worth keeping:
		//   null    nobody has asked yet
		//   'none'  asked, answered: this account holds no role
		//   'error' asked, and the ASK failed — not an answer, and must not be
		//           remembered as one
		//   <role>  asked, answered: the role held
		//
		// The distinction is the whole of it. An earlier version latched any
		// non-answer as "no role" for the life of the page, and the very first
		// ask happens while the drawer is drawn at boot — before the session
		// exists, so it 401s. The gateway was answering correctly the whole
		// time and the drawer had already decided never to ask again.
		var consoleRole = null;
		var consoleAsking = false;
		// Failed asks this page, so a momentary outage retries and a gateway
		// that is properly down does not spin.
		var consoleTries = 0;
		var CONSOLE_MAX_TRIES = 3;
		function renderConsoleLink() {
			// An account with no role gets no link and no repeat questions.
			if (consoleRole === 'none') return;
			if (consoleRole === null || consoleRole === 'error') {
				// Only worth asking once the session it rides actually exists.
				if (!(window.DaimondIdentity && DaimondIdentity.isUnlocked())) return;
				if (consoleAsking) return;
				consoleAsking = true;
				// Through `gwFetch`, which is the one copy of the 401 rule: a session
				// lives an hour, this drawer is opened long after that, and a bare fetch
				// answered its own 401 by remembering 'error' and asking again on the
				// next draw -- against a session that nothing here was renewing. It
				// self-heals, but only when something ELSE takes a session again, so a
				// role-holder could open the drawer all afternoon and never see the link.
				// `/api/admin` is neither an auth path nor one a bootstrap makes itself
				// (see isBootstrapOwn), so the renewal is allowed; and `whoami` takes the
				// session before it does anything, so the retry cannot repeat a side
				// effect the first attempt never had.
				DaimondGateway.gwFetch('/api/admin?view=whoami', {
					credentials: 'same-origin',
					headers: { 'x-daimond-api': String(DaimondGateway.clientApi()) },
				}).then(function (r) {
					// A 401 or 403 is the gateway declining to say, not a No.
					if (!r.ok) throw new Error('HTTP ' + r.status);
					return r.json();
				}).then(function (j) {
					consoleAsking = false;
					consoleTries = 0;
					consoleRole = (j && j.role) ? j.role : 'none';
					if (consoleRole !== 'none') renderHome();
				}).catch(function () {
					// Offline, no gateway, or not signed in yet: ask again next
					// time the drawer is drawn, rather than never.
					consoleAsking = false;
					consoleRole = 'error';
					// And ask again shortly, without waiting for that. Until now
					// the ONLY retry was closing the drawer and opening it, so a
					// role-holder whose one ask happened to fail sat looking at a
					// drawer with no way into the console and nothing saying why.
					// Only while the view is actually up: a closed drawer asks
					// again when it opens, and needs no timer to do it.
					if (consoleTries < CONSOLE_MAX_TRIES
						&& homeView && homeView.style.display !== 'none') {
						consoleTries++;
						setTimeout(function () {
							if (consoleRole === 'error'
								&& homeView.style.display !== 'none') renderHome();
						}, 1200 * consoleTries);
					}
				});
				return;
			}
			homeView.appendChild(el('div', 'admin-sec', t('home.sec_console')));
			var a = document.createElement('a');
			a.className = 'admin-console-link';
			a.href = '/console/';
			a.target = '_blank';
			a.rel = 'noopener';
			a.textContent = t('home.console_open');
			homeView.appendChild(a);
		}

		/// Ask what to call a device, and put the answer on its line.
		///
		/// An empty box is not a cancelled edit: it clears the name, which is a
		/// rename like any other and carries a stamp, so the clearing travels to
		/// the other devices too. Cancelling is what leaves everything alone.
		async function askDeviceName(id, shown) {
			var d = loadDevices()[id];
			// A live device can be on the panel from its presence beat alone, before its
			// roster line has reached this device (the disjoint-roster case the display
			// already handles). Rename has to work on it too, so the derived name -- and the
			// current value -- fall back to what the row is showing rather than returning
			// early, which is what left the pencil dead on those rows (owner trace, 2026-09-10).
			var derived = (d && d.name) || String(shown || '') || t('devices.unknown');
			var chosen = await promptDialog(t('devices.rename_title'), {
				message:     t('devices.rename_body', { derived: derived }),
				value:       (d && d.label) || '',
				placeholder: derived,
				okLabel:     t('common.save'),
				validate:    function () { return ''; },	// empty is how a name is cleared
			});
			if (chosen == null) return;					// cancelled, Escape, or the scrim
			renameDevice(id, chosen, derived);
			// The name is the user's own words, so it travels only inside the sealed
			// parcel — this asks for that parcel to go now rather than at the next
			// change, and does nothing at all when sync is off.
			if (window.DaimondSync && DaimondSync.nudge) {
				try { DaimondSync.nudge(); } catch (e) { /* not syncing */ }
			}
			renderHome();
		}

		/// Take a device off the list, having said plainly what that does and
		/// what it does not.
		///
		/// The confirm carries the limit rather than hiding it. A person removing
		/// a device is usually trying to sign it out, and this cannot do that —
		/// telling them afterwards, when the line reappears, would be the worst
		/// possible moment to find out.
		async function askRemoveDevice(id, shown) {
			// Belt: the ✕ is never drawn on this device's own row (id !== self,
			// above) and the prune-all button excludes it too, so this should be
			// unreachable for id === deviceId() -- but a caller that dials it
			// directly (a test hook, a future control) is stopped here rather than
			// reaching the gateway. The other half of the guard belongs at the
			// door itself, `sync.js removeDeviceRemote` -- out of scope for this
			// build (see the report); this is the belt without its braces yet.
			if (id === deviceId()) {
				try { noticeDialog(t('devices.remove_title'), tOr('devices.remove_self_body',
					'You cannot remove the device you are using.')); } catch (e) { /* best effort */ }
				return;
			}
			// THE ID TAIL AS WELL AS THE NAME. `deviceSelfName` already suffixes four hex
			// of the id for exactly this reason -- two of a user's Linux Chromes derive the
			// same words -- and removal is now irreversible from the device's side, so the
			// confirm has to name which one without relying on a label the user may not
			// have typed. The tail printed here is the one printed beside the row.
			var tail = String(id || '').slice(-4);
			var ok = await confirmDialog(
				t('devices.remove_body', { name: shown, tail: tail }),
				t('devices.remove'),
				{ title: t('devices.remove_title'), danger: true });
			if (!ok) return;
			// THE GATEWAY FIRST, then the roster line. The gateway's refusal is what makes
			// the removal real (owner ruling 2026-09-12); the tombstone is only what keeps
			// the line off a union-merged list. Doing the tombstone first on a failed call
			// would leave the device running, invisible, and still taking turns -- which is
			// the failure the ruling names, wearing the appearance of a fix.
			var res = { ok: false };
			try {
				// A paired native runner (R2f) is removed at its own door: the gateway
				// drops its row and bundle, disables its keys, and its next signed beat
				// is told 410, on which its keeper drops the account.
				var pv = (window.DaimondPresence && DaimondPresence.snapshot) ? DaimondPresence.snapshot() : null;
				if (pv && pv[id] && pv[id].kind === 'runner' && window.DaimondGateway && DaimondGateway.gwFetch) {
					var r = await DaimondGateway.gwFetch('/api/runner/pair/remove', {
						method: 'POST', credentials: 'same-origin',
						headers: { 'content-type': 'application/json' },
						body: JSON.stringify({ device: id }),
					});
					res = { ok: !!(r && r.ok) };
				} else if (window.DaimondSync && DaimondSync.removeDevice) {
					res = await DaimondSync.removeDevice(id);
				}
			} catch (e) { res = { ok: false }; }
			if (!res || !res.ok) {
				noticeDialog(t('devices.remove_title'), t('devices.remove_failed'));
				return;
			}
			removeDevice(id);
			// The removal travels only inside the sealed parcel; this asks for that
			// parcel to go now rather than at the next change, and does nothing at
			// all when sync is off.
			if (window.DaimondSync && DaimondSync.nudge) {
				try { DaimondSync.nudge(); } catch (e) { /* not syncing */ }
			}
			renderHome();
		}

		/// PAIR A COMPUTER AS A RUNNER (FIRST-RUN MINT-UI). The press mints a pairing token at
		/// the gateway and shows the one line to run on that computer, with Copy and how long
		/// it lasts; a second press mints a fresh one. The token is the computer's way in until
		/// it joins, so it lives in this row and nowhere else: never stored, synced or logged,
		/// and gone from the row when the gateway's ten minutes are up. Only a signed-in device
		/// can mint (the door is session-authed), so it is shown only on the device that asked.
		/// PAIR A COMPUTER BY ITS CODE (PAIR-QR). The computer's `runner pair` shows a QR and a
		/// short code; the camera opens the QR, and this is the way in when the camera's
		/// browser is not the one he is signed in on. The dialog is pairing.js's.
		function runnerCodeRow(view) {
			var go = document.createElement('button');
			go.type = 'button';
			go.className = 'admin-item';
			go.textContent = t('devices.runner_code');
			go.addEventListener('click', function () { DaimondPairing.runner.enterCode(); });
			view.appendChild(go);
		}

		var RUNNER_MINT_URL = '/api/runner/pair/mint';
		var RUNNER_MINT_CMD = '/opt/kimberlite/bin/runner pair ';
		var RUNNER_MINT_TOKEN_RE = /^[A-Za-z0-9_-]{8,128}$/;
		// The line on show, in memory only, so a redraw of the list (a beat, a rename) keeps
		// it rather than wiping it mid-copy: { line, until } or null.
		var _runnerMinted = null;
		function runnerMintRow(view) {
			var go = document.createElement('button');
			go.type = 'button';
			go.className = 'admin-item';
			go.textContent = t('devices.runner_mint');
			var out = document.createElement('div');
			view.appendChild(go);
			view.appendChild(out);
			var lapse = null;
			function clear() {
				if (lapse) clearTimeout(lapse);
				lapse = null;
				while (out.firstChild) out.removeChild(out.firstChild);
			}
			function say(msg) { clear(); out.appendChild(el('div', 'admin-note', msg)); }
			function show(line, ms) {
				clear();
				// Laid out as a device row, so its Copy sits in the same right-hand column as
				// every device's: the line in the name cell, Copy in the copy cell, and an
				// unseen rename-sized slot holding the rename column open.
				var row = el('div', 'device-row');
				var cell = row.appendChild(el('div', 'device-name'));
				cell.appendChild(el('pre', 'capp-conflict-code', line));
				row.appendChild(idCopyBtn(t('devices.runner_mint_what'), line));
				var acts = row.appendChild(el('div', 'device-acts'));
				var slot = acts.appendChild(el('span', 'device-rename'));
				slot.setAttribute('aria-hidden', 'true');
				slot.style.visibility = 'hidden';
				out.appendChild(row);
				out.appendChild(el('div', 'admin-note',
					t('devices.runner_mint_expiry', { n: Math.max(1, Math.round(ms / 60000)) })));
				lapse = setTimeout(function () {
					lapse = null;
					_runnerMinted = null;
					say(t('devices.runner_mint_lapsed'));
				}, ms);
			}
			if (_runnerMinted && _runnerMinted.until > Date.now()) {
				show(_runnerMinted.line, _runnerMinted.until - Date.now());
			}
			go.addEventListener('click', async function () {
				if (go.disabled) return;
				go.disabled = true;
				var j = null, status = 0;
				try {
					var r = await DaimondGateway.gwFetch(RUNNER_MINT_URL, {
						method: 'POST', credentials: 'same-origin', cache: 'no-store',
					});
					status = (r && r.status) || 0;
					if (r && r.ok) j = await r.json();
				} catch (e) { j = null; }
				go.disabled = false;
				var tok = (j && j.ok === true && typeof j.token === 'string'
					&& RUNNER_MINT_TOKEN_RE.test(j.token)) ? j.token : '';
				if (!tok) {
					_runnerMinted = null;
					say(status === 401 ? t('devices.runner_mint_signin') : t('devices.runner_mint_failed'));
					return;
				}
				var line = RUNNER_MINT_CMD + tok;
				var ms = (Number(j.expires_in) > 0 ? Number(j.expires_in) : 600) * 1000;
				_runnerMinted = { line: line, until: Date.now() + ms };
				show(line, ms);
			});
		}

		function el(tag, cls, text) {
			var n = document.createElement(tag);
			n.className = cls;
			if (text != null) n.textContent = text;
			return n;
		}

		// ── The status header ─────────────────────────────────
		// Each row answers a question the user would otherwise have to open
		// something to answer, and each row that can be acted on goes there.

		/// A row: a state dot, a label, a value, and an optional right-hand figure.
		function row(id, dot, label, val, aside, lock) {
			var r = document.getElementById(id);
			if (!r) return;
			r.innerHTML = '';
			var d = el('span', 'astat-dot' + (dot ? ' ' + dot : ''));
			r.appendChild(d);
			if (label) r.appendChild(el('span', 'astat-label', label));
			r.appendChild(el('span', 'astat-val', val));
			if (lock) {
				var l = el('span', 'astat-lock', '\u{1F512}');    // a padlock
				l.title = lock;
				r.appendChild(l);
			}
			// An aside is words, or a node holding a price tag.
			if (aside) {
				var as = el('span', 'astat-aside', typeof aside === 'string' ? aside : '');
				if (typeof aside !== 'string') as.appendChild(aside);
				r.appendChild(as);
			}
		}

		/// THE ONE LINE a person who is not debugging reads.
		///
		/// Eight diagnostic rows stood here on a fresh account and answered eight
		/// questions nobody had asked (audit 2026-09-15, STRIP-01). This answers the
		/// one they do have -- is it working, and is my work anywhere but here -- and
		/// the eight are behind it, unchanged, one press away.
		///
		/// A LADDER, most blocking first: a locked device can do nothing, an account
		/// that does not exist cannot sync, and a model that cannot run is what stops
		/// the next thing the user tries. Only when all three are fine does the line
		/// talk about sync, which is the state it is named for.
		/// THE EXCEPTIONS (D-20261015-15): what needs the person, one row and one act
		/// each, red first. The rules are js/needs.js's and tested there; this reads
		/// the facts and runs the acts. Shown even when the section is folded.
		var needPots = [];
		/// The shut status's one voice (`#astat-flag`): how many needs wait behind the fold, else the
		/// summary's fault, else nothing. The CSS shows it only where those rows are folded away.
		var needFlag = { n: 0, tone: 'warn' }, sumFault = '';
		function paintFlag() {
			var flag = document.getElementById('astat-flag');
			if (!flag) return;
			var fv = flag.querySelector('.astat-val'), fd = flag.querySelector('.astat-dot');
			var n = needFlag.n;
			var text = n ? tOr(n === 1 ? 'astat.needs_one' : 'astat.needs_other', n === 1 ? '{n} needs you' : '{n} need you', { n: n }) : sumFault;
			if (fv) fv.textContent = text;
			if (fd) fd.className = 'astat-dot ' + (n ? needFlag.tone : 'warn');
			if (n) flag.dataset.need = '1'; else delete flag.dataset.need;
			flag.hidden = !text;
		}

		function renderNeeds() {
			var box = document.getElementById('astat-needs');
			var N = window.DaimondNeeds;
			if (!box || !N) return;
			if (pg.locked) { needFlag = { n: 0, tone: 'warn' }; paintFlag(); N.paint(box, [], tOr, function () {}); return; }
			var M = window.DaimondModels;
			var stalled = null;
			try {
				var S = window.DaimondSync;
				if (S && S.chip && S.chip() === 'stalled' && S.lastSyncedAt && S.lastSyncedAt()) {
					stalled = Date.now() - S.lastSyncedAt();
				}
			} catch (e) { stalled = null; }
			var rows = N.compute({
				hand: (window.DaimondHandMode && DaimondHandMode.get) ? DaimondHandMode.get() : '',
				pots: needPots,
				updateReady: !!(window.DaimondRelease && DaimondRelease.isBehind && DaimondRelease.isBehind()),
				syncStalledMs: stalled,
				noModel: !(M && M.ready()),
			});
			// Folded on a phone the rows are behind the chevron, bar Bypass, which stands (D-20261015-15);
			// the flag says how many wait there (RAILSTATUS C).
			var hid = rows.filter(function (r) { return r.id !== 'bypass'; });
			needFlag = { n: hid.length, tone: hid.some(function (r) { return r.tone === 'bad'; }) ? 'bad' : 'warn' };
			paintFlag();
			N.paint(box, rows, tOr, function (r) {
				if (r.act === 'guard') { if (window.DaimondHandMode) DaimondHandMode.set('guarded'); }
				else if (r.act === 'topup') {
					if (r.url) window.open(r.url, '_blank', 'noopener');
					else if (r.pot === 'credits') openCredits('');
					else openSettings('');
				}
				else if (r.act === 'reload') location.reload();
				else if (r.act === 'retry') { if (window.DaimondSync && DaimondSync.nudge) DaimondSync.nudge(); }
				else if (r.act === 'connect') openSettings('');
				setTimeout(renderNeeds, 0);
			});
		}
		if (window.DaimondNeeds) DaimondNeeds.refresh = function () { try { renderNeeds(); } catch (e) { /* before boot */ } };

		function renderStatusSummary() {
			var el = document.getElementById('astat-summary');
			if (!el) return;
			var dot = 'ok', text = '';
			var fault = false;	// a warning the shut section must still voice
			var devices = 0;
			try { devices = Object.keys(collectDevices() || {}).length; } catch (e) { devices = 0; }
			// The chip's one word (`DaimondSync.chip`). `DaimondSync.state()` is the engine's
			// facts as an object, and reading it here matched none of the words below: the
			// line said "This device only" through every stall (D072).
			var sync = '';
			try { sync = (window.DaimondSync && DaimondSync.chip) ? String(DaimondSync.chip() || '') : ''; }
			catch (e) { sync = ''; }
			if (pg.locked) {
				dot = 'off'; text = tOr('astat.sum_locked', 'Locked');
			} else if (neverHeldAnIdentity()) {
				dot = 'warn'; fault = true; text = tOr('astat.sum_no_account', 'Not signed in');
			// No model is not the calm line's to say: the "No model · Connect" exception
			// row above it says so (renderNeeds), and S1x keeps the line to sync alone.
			} else if (sync === 'off' || sync === 'stalled') {
				dot = 'warn'; text = tOr('astat.sum_offline', 'Offline');
				// A plan without sync also reads 'off' (`restStatus` in js/sync.js): that is
				// what the plan is, not a fault, so only a stall or a safe start is voiced.
				var safe = false;
				try { safe = !!(window.DaimondSafe && DaimondSafe.on()); } catch (e) { safe = false; }
				fault = sync === 'stalled' || safe;
			} else if (sync === 'partial') {
				// Everything but the files travels; see `restStatus` in js/sync.js.
				dot = 'warn'; fault = true; text = tOr('astat.sum_partial', 'Synced, but not files');
			} else if (sync === 'synced' && devices > 1) {
				dot = 'ok'; text = tOr('astat.sum_synced_n', 'Synced \u00b7 {n} devices', { n: devices }) + syncWhen();
			} else if (sync === 'synced') {
				dot = 'ok'; text = tOr('astat.sum_synced', 'Synced') + syncWhen();
			} else {
				dot = 'off'; text = tOr('astat.sum_local', 'This device only');
			}
			// The key lives only in this browser (spec §5.1, R1): a fault until a passkey or a
			// confirmed recovery file covers it, voiced here (and as its Pending row) and never
			// as a sync state. BELOW EVERY FAULT ABOVE: it masked a stalled or refused sync when
			// it was the chip's word (QA M3), so it takes only a line that is not one already.
			if (!fault && !pg.locked && Pending.unrecoverable()) {
				dot = 'warn'; fault = true; text = tOr('recover.not_yet', 'Not recoverable yet');
			}
			row('astat-summary', dot, '', text);
			// A calm line has no dot to read (STATUS-REVIEW S1): muted words only.
			el.classList.toggle('astat-calm', !fault);
			el.title = tOr('astat.sum_help', 'Details');
			// The shut section's one voice: only a fault passes the importance filter
			// (no model, a stalled sync or a safe start, partial files, not signed in),
			// so an ordinary, merely local or unentitled state leaves the line silent.
			sumFault = fault ? text : '';
			paintFlag();
		}

		/// " · just now": how long since a round worked, for the calm line.
		function syncWhen() {
			try {
				var S = window.DaimondSync, at = S && S.lastSyncedAt ? S.lastSyncedAt() : 0;
				return (at && S.whenAgo) ? ' \u00b7 ' + S.whenAgo(at) : '';
			} catch (e) { return ''; }
		}

		/// Redraw the status. Cheap, and safe to call from anywhere that changes
		/// something the header reports.
		function status() {
			if (!document.getElementById('astat-model')) return;
			renderStatusSummary();

			// The models. This row used to name the ONE provider and model the app held; it now
			// counts what every provider between them can run, because that is the number that
			// changes when a key is added and the number a user wants to see go up.
			var mrow = document.getElementById('astat-model');
			var M = window.DaimondModels;
			var ready = M && M.ready();
			if (pg.locked) {
				row('astat-model', 'off', '', 'Locked');
			} else if (ready) {
				var n = M.count();
				row('astat-model', 'ok', '', t('drawer.models'), String(n));
			} else if (M && M.providers().length) {
				// A key is held but nothing is starred, or the key cannot be read.
				row('astat-model', 'warn', '', t('drawer.models'), String(M.count()));
			} else {
				row('astat-model', 'warn', '', t('astat.no_model'));
			}
			mrow.title = t('astat.model_help');
			// Until there is a model to think with, Daimond cannot answer anything, so this row is
			// the one thing to do — and it pulses to say so, rather than a form springing open over
			// the whole panel the moment the app loads.
			mrow.classList.toggle('astat-pulse', !pg.locked && !ready);

			// The account service: credits, and whether it can be reached at all.
			//
			// A session and a figure read under it decide this row. `navigator.onLine` does
			// NOT: it is the browser's guess, false whenever its own connectivity probe
			// fails -- network or no network -- and it used to be asked first, so one machine
			// guessing wrongly replaced a signed-in account's balance with "Offline" while
			// that same tab went on fetching, syncing and spending. The guess may still NAME a
			// connection that has actually failed; it may not overrule one that has not.
			var arow = document.getElementById('astat-account');
			var st = (window.DaimondGateway && DaimondGateway.state()) || {};
			// NOT gated on having a Daimond account, and that was the bug: the
			// money rows used to be drawn only for an authed account, so somebody
			// running on their own key with no account -- the commonest BYOK case
			// there is -- saw nothing at all about the money paying for their work.
			// Whether there is an account is one input to what may be said, not a
			// precondition for saying anything.
			// `proRow`, `tools` and `storage` are not about the account row and must
			// run either way. Drawn HERE as well as at the foot, because this return
			// skipped all three: an account with a balance -- which is to say, any
			// account the money rows can draw for -- saw a Pro row, a Tools count and
			// a storage figure frozen at whatever they happened to be the first time
			// the panel drew, with no way to refresh them short of a reload.
			if (!pg.locked && moneyRows(st, arow)) { proRow(); tools(); storage(); renderNeeds(); return; }
			arow.style.display = '';
			row('astat-account', 'off', '',
				pg.locked ? t('astat.locked')
					: !navigator.onLine ? t('astat.offline')
					: st.offline ? t('astat.service_unreachable')
					: t('astat.no_account'));
			arow.title = t('astat.credits_help');
			byokRow(null);

			// Pro: whether this identity owns the one-time unlock, and a way in if
			// not. It sits on its own row, next to credits but distinct from them --
			// Pro is a capability you own, credits are money you spend.
			proRow();

			// What Daimond can do. A user who does not know it can read a page or answer an
			// email will never ask it to, so the count sits in the rail and the panel is one
			// click from it.
			tools();

			// The workspace: OPFS is evictable, and a user who cannot see it
			// filling up cannot know to get anything out of it.
			storage();
			needPots = [];
			renderNeeds();
		}

		/// The money rows: up to two, each named by whose money it is.
		///
		/// The wording rules live in `js/money.js` and are tested there. This
		/// function does the drawing and nothing else, so a change to what may
		/// honestly be said is made in one place.
		///
		/// The row this replaced said "Credits" and showed the Daimond balance
		/// alone -- so somebody running on their own key read "Credits $0.00"
		/// while that key was paying for everything.
		/// Returns whether it drew anything, so the caller can fall back to
		/// saying why there is nothing to draw.
		function moneyRows(st, arow) {
			var M = window.DaimondMoney;
			if (!M) return false;          // a stripped build: the caller's line is better than none
			var pools = moneyPools(st);
			var list = moneyList(st, pools);

			// The Status row's Top Up reads each pool's 24 h rate, never the dial's 15 min one:
			// a busy quarter-hour is not a reason to go and pay.
			needPots = pools.map(function (p) {
				return { key: p.key, provider: p.provider || '', minutesDay: p.minutesDay, label: p.label,
					what: p.label };
			});
			if (!list.length) {
				// Nothing true to say about any pot. Not a dash -- an empty place
				// where a figure goes reads as zero -- and not a blank row either:
				// the caller says WHY instead.
				byokRow(null);
				return false;
			}
			var first = list[0];
			arow.style.display = '';
			row('astat-account', first.tone, '', first.label, moneyValue(first));
			arow.title = moneyTitle(first);
			byokRow(list.length > 1 ? list[1] : null);
			return true;
		}

		/// What a money row shows: the consequence when it is at risk, the
		/// figure otherwise.
		function moneyValue(r) {
			if (r.atRisk && r.minutes !== null) {
				return t('money.left_at_rate', { mins: Math.max(1, Math.round(r.minutes)) });
			}
			// The Daimond balance is the account's own money, in the account's own
			// currency, and the gateway's formatter is the one that knows both. A
			// provider's balance is quoted in USD by the provider, so that one is
			// USD and saying otherwise would be a conversion nobody performed.
			var est = { estimated: r.kind === 'estimate' };
			var mark = (r.key === 'credits' && r.minor !== null && r.minor !== undefined)
				? DaimondI18n.priceMarkMinor(r.minor, r.currency, est)
				: DaimondI18n.priceMark(r.usd, est);
			if (!mark) return '';
			return DaimondI18n.fillPrices(document.createElement('span'),
				r.kind === 'spent' ? t('money.spent_so_far', { amt: mark }) : mark);
		}
		function moneyTitle(r) {
			if (r.kind === 'spent')    return t('money.spent_help');
			if (r.kind === 'estimate') return t('money.estimate_help');
			return t('astat.credits_help');
		}

		/// The second money row, drawn only when there is a second pot.
		function byokRow(r) {
			var el2 = document.getElementById('astat-byok');
			if (!el2) return;
			if (!r) { el2.style.display = 'none'; return; }
			el2.style.display = '';
			row('astat-byok', r.tone, '', r.label, moneyValue(r));
			el2.title = moneyTitle(r);
		}

		/// The Pro row: active, paused, or an invitation to subscribe. Shown only
		/// when the gateway has answered for an account, since Pro is a fact about
		/// that account -- a locked or unconnected app cannot say, so it says
		/// nothing.
		///
		/// A paused subscription is its own state and not a lapse: billing was
		/// paused while the account was away and resumes on use, so the row says
		/// paused, not "upgrade", at somebody who is a subscriber in good standing.
		function proRow() {
			var r = document.getElementById('astat-pro');
			if (!r) return;
			var st = (window.DaimondGateway && DaimondGateway.state()) || {};
			if (pg.locked || !st.authed || st.pro === null) { r.style.display = 'none'; return; }
			r.style.display = '';
			if (st.pro) {
				row('astat-pro', 'ok', 'Pro', t('astat.pro_owned'));
				r.title = t('astat.pro_owned_help') + ' ' + proTermLine(st);
			} else if (proPaused(st)) {
				row('astat-pro', 'off', 'Pro', t('astat.pro_paused'));
				r.title = t('astat.pro_paused_help');
			} else if (proHasEnded(st)) {
				row('astat-pro', 'off', 'Pro', t('astat.pro_ended'));
				r.title = t('astat.pro_ended_help');
			} else {
				row('astat-pro', 'off', 'Pro', t('astat.pro_upgrade'));
				r.title = t('astat.pro_upgrade_help');
			}
			// The value reads as a link whenever there is something to do -- a
			// subscribe, or a resume for a paused subscription.
			r.classList.toggle('astat-pro-upgrade', !st.pro);
		}

		/// The Pro popup: subscribe, resume a paused subscription, or -- when it is
		/// held -- the confirmation of where it stands with the option to cancel.
		/// Its own surface rather than the Credits drawer, because Pro is a single
		/// decision, not a balance to watch.
		async function showPro() {
			var st = (window.DaimondGateway && DaimondGateway.state()) || {};

			// Held and active: confirm, and offer to cancel at the period end.
			if (st.pro && !proPaused(st)) {
				var cancel = await confirmDialog(
					t('pro.owned_plain') + '\n\n' + proTermLine(st),
					t('pro.cancel'),
					{ title: 'Daimond Pro', danger: false, cancelLabel: t('dlg.done') });
				if (!cancel) return;
				var yes = await confirmDialog(t('pro.cancel_confirm'), t('pro.cancel'),
					{ title: t('pro.cancel'), danger: true, cancelLabel: t('dlg.not_now') });
				if (!yes) return;
				try { await DaimondGateway.cancelPro(); status(); }
				catch (e) { noticeDialog(t('pro.checkout_failed'), friendlyError(e)); }
				return;
			}

			// Paused: one tap resumes it, with no trip to Stripe.
			if (proPaused(st)) {
				var resume = await confirmDialog(t('pro.paused_plain'), t('pro.resume'),
					{ title: t('astat.pro_paused'), danger: false, cancelLabel: t('dlg.not_now') });
				if (!resume) return;
				try { await DaimondGateway.resumePro(); status(); }
				catch (e) { noticeDialog(t('pro.checkout_failed'), friendlyError(e)); }
				return;
			}

			// Otherwise an offer to subscribe. The checkout behind the button goes
			// through: the gateway refuses a second subscription only while one is
			// granting.
			// A card charge, so it says US dollars: the statement reads in them.
			var price = st.proPriceMinor ? DaimondGateway.fmtBilled(st.proPriceMinor, st.currency) : '';
			var ok = await confirmDialog(
				t('pro.offer_plain'),
				proBuyLabel(st, price),
				{ title: t('astat.pro_upgrade'), danger: false, cancelLabel: t('dlg.not_now') });
			if (!ok) return;
			try {
				var r = await DaimondGateway.buyPro();       // navigates to Stripe, or returns {held}
				if (r && r.held) { await DaimondGateway.refreshLicence(); status(); }
			} catch (e) {
				noticeDialog(t('pro.checkout_failed'), friendlyError(e));
			}
		}

		/// The Tools row: how many tools this Daimond holds, of how many exist.
		function tools() {
			var r = document.getElementById('astat-tools');
			if (!r) return;
			if (pg.locked || !window.DaimondTools) { r.style.display = 'none'; return; }
			r.style.display = '';
			var c = DaimondTools.counts();
			// Before the gateway has answered, the total is only what is built in, and a row
			// reading "16 of 16" would quietly claim there is nothing else to have.
			var val = c.all > c.have
				? t('astat.tools_of', { have: c.have, all: c.all })
				: t('astat.tools', { have: c.have });
			row('astat-tools', 'ok', '', val);
			r.title = t('astat.tools_help');
			r.onclick = function () { DaimondTools.show(); };
		}

		var _storeSeq = 0;

		/// The sandbox. Its size is the browser's to know, and it will say: `estimate()` gives what
		/// this origin uses and the quota it is allowed, which is what turns "2.0 MB" -- a figure
		/// with nothing to compare it to -- into a fraction of something.
		///
		/// "Evictable" is not a warning about the workspace, it is a fact about the browser:
		/// storage that has not been marked persistent may be thrown away under pressure. The row
		/// says so, and offers the one thing that fixes it.
		function storage() {
			var r = document.getElementById('astat-store');
			if (!r) return;
			if (pg.locked || !navigator.storage || !navigator.storage.estimate) { r.style.display = 'none'; return; }
			var seq = ++_storeSeq;
			navigator.storage.estimate().then(async function (e) {
				if (seq !== _storeSeq) return;                 // superseded
				var kept = false;
				try { kept = await navigator.storage.persisted(); } catch (x) { /* unsupported */ }
				var used  = e.usage || 0;
				var quota = e.quota || 0;
				var pct   = quota ? (100 * used / quota) : 0;
				// A percentage that rounds to zero is a lie of precision, not a reassurance: say
				// "under 0.1%" rather than "0.0%", which reads as "nothing" when it is not nothing.
				var pctTxt = !quota ? '' : (pct < 0.1 ? '<0.1%' : pct.toFixed(1) + '%');

				r.style.display = '';
				// "evictable" is a browser-engine word and it was on the row itself,
				// beside a byte figure, on every account that had never asked for
				// permanent storage (audit STRIP-02). The row says what is stored and
				// how much; whether the browser may reclaim it is the dot's colour and
				// the tooltip's sentence, which is where an offer to fix it belongs.
				row('astat-store', kept ? 'ok' : 'off', '', t('astat.workspace_browser'),
					fmtBytes(used) + (pctTxt ? ' · ' + pctTxt : ''));
				// The fix for evictable is one call, and it is the user's to make -- but
				// only while it can change something. Once refused, or with no API to ask,
				// the row is plain status, and its tooltip does not invite the ask.
				var ask = storeAskable(navigator.storage, kept);
				var tip = kept ? t('astat.store_persistent') : (ask ? t('astat.store_evictable') : '');
				r.title = ((quota
						? t('astat.store_of', { used: fmtBytes(used), quota: fmtBytes(quota) })
						: '') + (tip ? ' ' + tip : '')).trim();
				r.onclick = !ask ? null : async function () {
					var got = false;
					try { got = await navigator.storage.persist(); } catch (x) { /* refused */ }
					if (!got) {
						try { localStorage.setItem(STORE_REFUSED_KEY, '1'); } catch (x) { /* no store */ }
					}
					storage();
				};
				r.style.cursor = ask ? 'pointer' : '';
			}).catch(function () { r.style.display = 'none'; });

			native();
		}

		// The size walk of a real folder: what it has counted, and whether it was told to stop.
		var _walk = null;             // { stop: bool, files, bytes } while running
		var _walked = null;           // the last completed result

		/// The real folder, when there is one.
		///
		/// The browser tells us NOTHING about it: a FileSystemDirectoryHandle has no size, no
		/// quota, no usage, and there is no web API for free disk space. So unlike the sandbox
		/// row above, this one cannot show a percentage -- and rather than invent one, it offers
		/// to go and count, which on a large tree is a real walk over every file and is therefore
		/// asked for, warned about, and abandonable.
		function native() {
			var r = document.getElementById('astat-store-native');
			if (!r) return;
			var handle = (typeof Files !== 'undefined' && Files.folder) ? Files.folder() : null;
			var can = typeof window.showDirectoryPicker === 'function';
			if (pg.locked || !can) { r.style.display = 'none'; return; }
			r.style.display = '';

			if (!handle) {
				row('astat-store-native', 'off', '', t('astat.workspace_native'), t('astat.not_connected'));
				r.title = t('astat.native_help');
				r.style.cursor = 'pointer';
				r.onclick = function () { DaimondPanels.show('work'); };
				return;
			}

			if (_walk) {
				row('astat-store-native', 'warn', '', t('astat.workspace_native'),
					t('astat.n_files', { n: fmtCount(_walk.files) }) + ' · ' + fmtBytes(_walk.bytes));
				r.title = t('astat.counting');
				r.style.cursor = 'pointer';
				r.onclick = function () { _walk.stop = true; };
				return;
			}

			var done = _walked && _walked.name === handle.name;
			row('astat-store-native', 'ok', '', t('astat.workspace_native'),
				done ? fmtBytes(_walked.bytes) + (_walked.partial ? ' ' + t('astat.part') : '') : handle.name);
			r.title = done
				? t(_walked.partial ? 'astat.counted_partial' : 'astat.counted',
						{ n: fmtCount(_walked.files), folder: handle.name })
					+ ' ' + t('astat.count_again')
				: t('astat.count_offer');
			r.style.cursor = 'pointer';
			r.onclick = function () { estimate(handle); };
		}

		/// Walk the folder, adding up what is in it, and stop the moment it is told to.
		///
		/// The walk yields to the event loop every so often. That is what makes it abandonable:
		/// a loop that never yields would hold the main thread and the Stop it is checking for
		/// could never be clicked.
		async function estimate(handle) {
			if (_walk) return;
			_walk = { stop: false, files: 0, bytes: 0 };
			native();
			var stack = [handle];
			try {
				while (stack.length && !_walk.stop) {
					var dir = stack.pop();
					for await (var ent of dir.values()) {
						if (_walk.stop) break;
						if (ent.kind === 'directory') { stack.push(ent); continue; }
						try {
							var f = await ent.getFile();
							_walk.files += 1;
							_walk.bytes += f.size;
						} catch (e) { /* a file that will not open is still a file we cannot size */ }
						// Breathe: let the click that stops this actually be heard, and let the
						// count on screen keep up with the walk.
						if (_walk.files % 40 === 0) {
							native();
							await new Promise(function (res) { setTimeout(res, 0); });
						}
					}
				}
			} catch (e) { /* the folder went away mid-walk; the numbers so far still stand */ }
			_walked = {
				name:    handle.name,
				files:   _walk.files,
				bytes:   _walk.bytes,
				partial: _walk.stop,
			};
			_walk = null;
			native();
		}

		function fmtCount(n) {
			return String(n || 0).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
		}
		function fmtBytes(n) {
			if (n < 1024) return n + ' B';
			if (n < 1048576) return (n / 1024).toFixed(0) + ' KB';
			if (n < 1073741824) return (n / 1048576).toFixed(1) + ' MB';
			return (n / 1073741824).toFixed(2) + ' GB';
		}

		/// Logging out clears the user's content from the DOM. Their API key is
		/// theirs, and it is now sitting in a panel rather than a hidden modal.
		function clear() {
			endForm();
			setSecret(document.getElementById('cfg-api-key'), '');
			// The push token goes with it. It is masked, so what a half-filled box
			// leaves behind is not on screen -- but it is on `el._real`, which is
			// exactly the copy a locked app must not still be holding.
			setSecret(document.getElementById('cfg-push-token'), '');
			var pn = document.getElementById('push-note');
			if (pn) pn.textContent = '';
			document.getElementById('byok-note').textContent = '';
			document.getElementById('credits-balance').textContent = '';
			document.getElementById('credits-packs').innerHTML = '';
			closeAdmin();
			status();
		}

		function init() {
			body         = document.getElementById('admin-scroll');   // the views' container
			homeView     = document.getElementById('admin-home');
			settingsView = document.getElementById('admin-models');
			creditsView  = document.getElementById('admin-credits');
			releaseView  = document.getElementById('admin-release');
			pushView     = document.getElementById('admin-push');
			limitsView   = document.getElementById('admin-limits');
			searchView   = document.getElementById('admin-search');
			foldersView  = document.getElementById('admin-folders');
			formView     = document.getElementById('admin-form');
			modal        = document.getElementById('settings-modal');
			slot         = document.getElementById('settings-slot');
			closeBtn     = document.getElementById('settings-close');
			closeBtn.addEventListener('click', closeModal);
			// How each view draws itself. See `repaint`. The form view is absent on
			// purpose: it is a question a caller is waiting on an answer to, and its
			// strings are marked as they are built instead.
			painter(homeView,     renderHome);
			// The model list, and not `fillSettings`: that re-seeds the provider box from
			// `cfg` and can go to the network, and a language change must not take a
			// half-typed key with it -- the same call the push view makes for the same reason.
			painter(settingsView, function () {
				if (window.DaimondModels) DaimondModels.render();
			});
			painter(limitsView,   renderLimitRows);
			painter(searchView,   drawSearch);
			painter(foldersView,  drawFolders);
			painter(creditsView,  function () {
				// Only a note the CALLER put there survives, and it survives because
				// `apply` has just put it into the new language -- which is what the
				// mark on it means. A line `renderCredits` wrote carries no mark and
				// is that function's to write again, so passing it back here would
				// paste the old language over the new one.
				var n = document.getElementById('credits-note');
				drawCredits(n && n.hasAttribute('data-i18n') ? n.textContent : '');
			});
			painter(releaseView,  drawRelease);
			// `renderPushState`, not `fillPushSettings`: the latter empties the token
			// box, and a language change must not take a half-typed credential with
			// it. Only the one line that reads as a sentence needs redrawing.
			painter(pushView,     renderPushState);
			// One registration for the whole drawer, wherever it is standing: in the
			// rail, or in the modal a window too narrow for a rail puts it in.
			if (window.DaimondI18n) {
				DaimondI18n.surface(function () {
					if (modal.style.display !== 'none') return slot;
					return drawerOpen ? body : null;
				}, repaint);
			}
			adminWrap = document.getElementById('admin');
			titleEl   = document.getElementById('admin-drawer-title');
			var acl = document.getElementById('admin-close');
			if (acl) acl.addEventListener('click', closeAdmin);
			// THE DISCLOSURE over the eight diagnostic rows. Its state is remembered
			// per browser, because somebody who opened it once is a person who wants
			// it, and closed is what a first-time user gets.
			var sumRow = document.getElementById('astat-summary');
			var detail = document.getElementById('astat-detail');
			if (sumRow && detail) {
				// The diagnostic rows live in Settings now (mountStatusDetail); the calm line
				// opens Settings, where they are. Shut in the rail until Settings takes them.
				detail.hidden = true;
				sumRow.removeAttribute('aria-expanded');
				sumRow.setAttribute('aria-controls', 'admin-body');
				sumRow.addEventListener('click', function () { home(); });
			}
			// Each status row opens the thing it names, and nothing else.
			document.getElementById('astat-model').addEventListener('click', function () { openSettings(''); });
			document.getElementById('astat-account').addEventListener('click', function () { openCredits(''); });
			var proRowEl = document.getElementById('astat-pro');
			if (proRowEl) proRowEl.addEventListener('click', showPro);
			var relRow = document.getElementById('astat-release');
			if (relRow) relRow.addEventListener('click', release);
			// The build id, beside the row that names the version. Its value is
			// read at the press, not now: nothing has fetched build.json yet.
			mountBuildCopy();
			if (window.DaimondRelease) DaimondRelease.paintRow();
			var pushBtn = document.getElementById('push-save');
			if (pushBtn) pushBtn.addEventListener('click', function () { savePushCred(); });
			var addBtn = document.getElementById('models-add');
			if (addBtn) addBtn.addEventListener('click', function () {
				var f = document.getElementById('byok-form');
				if (f) f.style.display = f.style.display === 'none' ? '' : 'none';
			});
			modal.addEventListener('click', function (e) { if (e.target === modal) closeModal(); });
			// The rail comes and goes with the window width, and whatever is open has
			// to follow it. BOTH ways: only modal-to-panel was handled, so a window
			// shrinking past the fold took the rail away and left the open view with
			// nowhere to be. A half-filled form was the bad case — it vanished with
			// everything typed into it, re-opening the rail did not bring it back,
			// and nothing had said a word.
			window.addEventListener('resize', function () {
				var inModal  = modal.style.display !== 'none';
				if (!drawerOpen && !inModal) return;
				var formOpen = !!(formView && formView.style.display !== 'none');
				var title    = (titleEl && titleEl.textContent) || t('admin.settings');
				// Carry the heading's key across the move, or a drawer that has been
				// dragged narrow and back stops following a language change.
				var key      = titleEl ? titleEl.getAttribute('data-i18n') : null;
				if (available()) {
					if (inModal) { toPanel(); showDrawer(title, formOpen, key); }
				} else if (!inModal) {
					toModal(title, formOpen, key);
				}
			});
			// The dots are only true while they are true.
			window.addEventListener('online',  status);
			window.addEventListener('offline', status);
			// Coming back online drains the Social compose queue: notes written while
			// offline (or whose send failed) are posted now, each in the mode its
			// author chose -- a verbatim note goes straight through, a polish note
			// drafts on the model first. improve.js owns the draining; this is the one
			// event that tells it the network is back.
			window.addEventListener('online', function () {
				try { if (window.DaimondImprove && DaimondImprove.flushQueue) DaimondImprove.flushQueue(); }
				catch (e) { /* the panel may not be up; the queue survives for next time */ }
			});
			// A handle claimed on ANOTHER device arrives in a sync parcel, and the
			// row naming it is drawn in the home view. The local claim redraws
			// itself -- `doChangeHandle` calls `homeContent()` when the gateway
			// answers -- but the adopted one had nothing to do that, and
			// `identity.js` dispatched `daimond:handle` to nobody: claim a name on
			// device A, pull on device B, and B went on showing the name it had, or
			// no name at all, until something else redrew the drawer.
			//
			// `renderHome` and not `homeContent`, because this must not pull a user
			// who is reading Models or Credits back to Home. Nothing is redrawn
			// while the drawer is shut -- opening it renders anyway -- and the
			// narrow-window modal counts as standing open, since the same view is
			// what it is holding.
			window.addEventListener('daimond:handle', refreshHome);
			closeAdmin();   // the drawer starts hidden; only the Status strip shows
			status();
		}

		return {
			init: init, available: available, settings: settings, credits: credits,
			release: release, push: push,
			limits: limits, search: search, folders: folders, refreshHome: refreshHome,
			toggle: toggleSettings,
			home: home, homeContent: homeContent, form: form, closeModal: closeModal,
			clear: clear, status: status, summary: renderStatusSummary,
			// The "Not recoverable yet" Pending row's act: the enrolment, asked again.
			recover: function () { return offerRecovery(null, true); },
			close: closeAdmin,
		};
	})();

	// THE SUMMARY FOLLOWS THE CHIP. The rail's one line reads the sync chip, and the
	// chip changes on its own -- a round starting, landing, or stalling -- with nothing
	// else on the strip moving, so the line was only as fresh as the last repaint
	// something unrelated caused. sync.js says when the chip's word changes.
	window.addEventListener('daimond:sync-chip', function () {
		try { DaimondAdmin.summary(); } catch (e) { /* the panel is not up yet */ }
	});
	// And the record of what brings the identity back (identity.js `noteRecovery`, a pull's
	// `adoptRecover`, a create): the summary and the Pending row both follow it.
	window.addEventListener('daimond:recoverable', function () {
		try { DaimondAdmin.summary(); } catch (e) { /* the panel is not up yet */ }
		try { Pending.fresh(); Pending.render(); } catch (e) { /* before boot */ }
	});

	// Published on purpose. Two other modules already ask for `window.DaimondAdmin`
	// before sending the user to the Pro offer in Credits -- mail.js when its pitch
	// button is pressed, sync.js when the "Sync off" chip is clicked -- and until
	// now it was undefined, so the Mail panel's own Buy button did nothing at all.
	// One handle on the surface that already exists, rather than a second way in.
	window.DaimondAdmin = DaimondAdmin;
} // page-split: end install
